--All display-related strings must be listed here
--Sorted in lexicographical order, and organized by the following categories






--String constants must be uppercase, with multiple English words joined by underscores







--Interface text		AUI_* -> Interface String --Text displayed at a fixed position in the interface






--Dialog box text	DLG_* -> Dialog String --Prompt text displayed in a pop-up dialog box
--General text		GNR_* -> General String
--Message text		MSG_* -> Message String --Use MSG_ERR_* for returned error messages





--Interface hover tooltip	TIP_* -> Tip String
--Loading Tips LDG_TIP	LDG_TITLE
--Other text		TEXT_*
--Temporary test use	TMP_*

--The following strings are temporarily not placed in this file
--Button text		BTN_* -> Button String --Currently stored in the 界面.xml file







