						"Type: Confrontation, Boss Kill\rDifficulty:★★★\rLevel:58+\rMatchup:Yellow Turban Army VS Eastern Han Army\rYellow Turban Objective:Defeat Huangfu Song\rEastern Han Objective:Defeat Zhang Jue\rStory:\r    In the first year of Zhongping under Emperor Ling of Han (184 AD), at the call of Zhang Jue, the master of the Way of Great Peace, followers of the Way of Great Peace donned yellow headbands and went about proclaiming “The Blue Heaven is dead, the Yellow Heaven shall rise. In the year Jiazi, all under heaven shall prosper”, launching a great rebellion that swept across the whole country. The Eastern Han court was greatly alarmed and appointed He Jin as Grand General, dispatching the Northern Army and the troops of the commanderies and kingdoms to suppress the Yellow Turbans.\r    The main strength of the Yellow Turban Army was concentrated in three places: Jizhou, Yingchuan and Nanyang. Of these, the Yellow Turban Army at Yingchuan posed the greatest threat to the Han capital of Luoyang.\r    In the summer of the fourth month, Right Central Commandant Zhu Jun led a portion of his troops to the Yingchuan front, where he was driven back by Bo Cai, a subordinate of the Yingchuan Yellow Turbans. The other column of Left Central Commandant Huangfu Song saw that the Yellow Turbans were too strong and withdrew to Changshe to hold it. The Yingchuan Yellow Turbans then mobilized in force and advanced, employing encirclement tactics, and the fighting fell into a stalemate.",
