						"Type: Co-op, Defeat Boss\rDifficulty:★★\rLevel:15+\rConflict:Ma Chao's Army VS Western Qiang Army (NPC)\rObjective:Defeat Yan Xing within 40 minutes\rStory:\r    At the beginning of Jian'an, the Central Plains fell into chaos. In the distant Liangzhou, the factions of Ma Teng and Han Sui lived in outward peace while secretly vying with one another. One day, Ma Chao learned that Han Sui had sent a secret letter to the Qiang region. To investigate Han Sui's movements, Ma Chao, along with his cousins Ma Dai and Ma Tie, led a squad of warriors into the Qiang camp, intending to steal Han Sui's secret letter. And so the story unfolds...\r    To find out whether Han Sui and the Qiang were colluding, the player follows Ma Chao into the Qiang army's stronghold on a secret reconnaissance mission—but falls right into a Qiang ambush. After a grueling fight to break out of the encirclement, they are unexpectedly cut off and slain by Yan Xing, Han Sui's great general! At the same time, the Qiang King, King Midang, also leads the Qiang main force in pursuit from behind. In this desperate moment, can Ma Chao the Brocade display his divine might?",
