AUI_BATTLEFIELD[353] = {
						"Type: Co-op, Boss Kill\rDifficulty:★★★★\rLevel:80\rStory:\r    Xiakou belonged to Jiangxia Commandery of Jingzhou during the Eastern Han. Dividing the strategic advantage of Jingxiang while holding it down, it was an important military hub linking the two provinces of Jing and Yang — and also a key point that had to be seized when the Yangzhou forces in the southeast advanced upstream to the west. In the thirteenth year of Jian'an, Sun Quan led troops to campaign against Huang Zu and won over Gan Ning; from then on he securely held Xiakou, laying the foundation for the victory at Red Cliff. Eastern Wu thereafter built warships on a large scale and garrisoned troops along the riverbank; moreover, Sun Quan ordered Sun Jing to lead troops to defend Wu-Kuaiji; Sun Quan personally commanded the great army, stationing it at Chaisang; Chu Du trained the navy daily at Poyang Lake to prepare for the offensive.",
