AUI_BATTLEFIELD[354] = {
						"Type: Co-op, Boss Kill\rDifficulty:★★★★★★\rLevel:Hero 5+\rStory:\r    In the seventh year of Jian'an, Kongming lived in seclusion at Longzhong, studying under Master Water Mirror Sima Hui. Liang was fond of reading the 《Chant of Liangfu》, and often compared himself to Guan Zhong and Yue Yi. His reputation resounded throughout Jingzhou, and people called him the “Crouching Dragon.” At that time there was a famous scholar of Jingzhou, Huang Chengyan, who praised Liang's talent; he happened to have an unmarried daughter and wanted to take Liang as a son-in-law.\r    Huang Chengyan declared beforehand that if Zhuge Liang wished to marry Yueying, he must overcome trial after trial. Moreover, Yueying was renowned everywhere, intelligent as ice and snow, with countless admirers. These trials, it was feared, would be harder than strategy itself. So Zhuge Liang said: “If I am helped to win a wife, Liang will remember the kindness in his heart and surely repay it richly.” In an instant, every hero under heaven was stirred, and they flocked one after another to Longzhong.\r    The old master Huang Chengyan left behind a mysterious brocade bag — what unknown trials would Zhuge Liang's party face? A great courtship battle, condensing all the hardships of love, a contest of wits and strategy about to unfold (deploy).",
