						"Type: Story, Score Accumulation, Boss Defeat\rDifficulty: ★★★★★\rLevel: Hero Lv. 35+\rObjective: Accumulate 500 or more Score\rStory:\r      After the Battle of Red Cliff, Cao Cao withdrew north to hold his ground, Eastern Wu occupied Jiangnan, and Liu Bei seized Jingzhou — the tripartite balance had taken shape. Sun Quan demanded that Liu Bei “return” Jingzhou, but failed; so he set a plan in motion. Taking advantage of the recent death of Liu Bei's wife, under the guise of a marriage alliance, he gave Liu Bei his own sister, Lady Sun. Once they had lured Liu Bei to Eastern Wu, they would detain him there to exchange for Jingzhou. Little did they know that Zhuge Liang had long seen through Eastern Wu's scheme. He arranged the Brilliant Stratagem of the Brocade Bag, letting Liu Bei come away safe and sound, wed Lady Sun, and leave behind the saying “Chu Du's brilliant scheme pacified all under heaven, yet losing his lady cost him troops besides” (Chu Du's clever plan calmed the realm; he lost a wife and lost his army too).\r    Unexpectedly, after Lady Sun returned to Jingzhou she fell gravely ill and could not rise from her bed. Even after recovering, her mind wandered and she lapsed into unconsciousness. Zhuge Liang racked his brains, but could only discover that Lady Sun harbored an unresolvable knot in her heart, and that this was what had made her ill. After both medicine and acupuncture proved useless, Zhuge Liang proposed a method: to use the Soul-Returning Incense to enter Lady Sun's dream and trace the source of her affliction…",
						"Challenge Party",
						"Commoners of Eastern Wu",
						"",
						"",
						"",
						"",
						}
--ID:933 Peerless Hulao Pass Heroes' Gathering Heroic
AUI_BATTLEFIELD[933] = {
						"Type: Co-op, Boss Defeat\rDifficulty: ★★★★★★★\rLevel: Hero Lv. 40+\rOpponent: Coalition Army vs Dong Zhuo's Army (NPC)\rObjective: Defeat Dong Zhuo within 120 minutes\rStory:\r    In the first year of Xiping (189 AD), Dong Zhuo seized power, deceiving the emperor and harming the people. Cao Cao raised an army from Chenliu and summoned the lords of the eighteen circuits, nominating the Administrator of Bohai, Yuan Shao, as their leader. He issued a call to arms (a forged imperial edict) throughout the land and commanded hundreds of thousands of valiant troops, advancing on Luoyang. And barring the way before the eighteen circuits were the two passes of Sishui and Hulao.\r    Sishui Pass was held by Hua Xiong, Dong Zhuo's foremost general — one man guarding the pass, ten thousand unable to pass. Dong Zhuo himself led a two-hundred-thousand-strong army camped at Hulao Pass, famed as “the bolt barring the Central Skies, the throat of the Three Qins,” and ordered his sworn son, Lu Bu the Flying General, to pitch camp before the pass, glaring like a tiger (watching and waiting) for the coalition of lords to arrive. Flying General Lu Bu, unmatched in martial skill, ground his claws like a hungry tiger, ready to trample the majesty and confidence of the warriors of all under heaven. And within the coalition were three nameless minor generals, little known to anyone, about to blaze brilliantly before a thousand troops and ten thousand horses…",
						"Allied Army",
						"Dong Zhuo's Army",
						"Defeat Dong Zhuo",
