--Weapon
SpecailDesc0 = {}
SpecailDesc0[8] = "#N, after unremitting effort, successfully crafted #G, overjoyed beyond words and the envy of all!"
SpecailDesc0[12] = "#N, through tireless perseverance, finally forged #G; in that instant a sharp chill radiated from it, and all who saw it were awed!"
SpecailDesc0[15] = "Killing intent sharpens the edge — unstoppable! #N, relying on the sincerity of crystal and unyielding resolve, finally obtained #G — the entire court is shaken!"
SpecailDesc0[16] = "Killing intent sharpens the edge — unstoppable! #N, relying on the sincerity of crystal and unyielding resolve, finally obtained #G — the entire court is shaken!"
SpecailDesc0[17] = "Killing intent sharpens the edge — unstoppable! #N, relying on the sincerity of crystal and unyielding resolve, finally obtained #G — the entire court is shaken!"
SpecailDesc0[18] = "Killing intent sharpens the edge — unstoppable! #N, relying on the sincerity of crystal and unyielding resolve, finally obtained #G — the entire court is shaken!"
SpecailDesc0[19] = "Killing intent sharpens the edge — unstoppable! #N, relying on the sincerity of crystal and unyielding resolve, finally obtained #G — the entire court is shaken!"
SpecailDesc0[20] = "Kill a man in ten paces, leave no trace across a thousand li! When a divine weapon appears, heaven weeps, earth laments, and spirits quake! Who in all the world can rival #N, who now holds #G!"
SpecailDesc0[21] = "Three moves to take a high general's head — one man can hold back ten thousand! With this divine artifact in hand, who dares face me in battle! #N, holding #G, sighed thus."
SpecailDesc0[22] = "Three moves to take a high general's head — one man can hold back ten thousand! With this divine artifact in hand, who dares face me in battle! #N, holding #G, sighed thus."
SpecailDesc0[23] = "Three moves to take a high general's head — one man can hold back ten thousand! With this divine artifact in hand, who dares face me in battle! #N, holding #G, sighed thus."
SpecailDesc0[24] = "Three moves to take a high general's head — one man can hold back ten thousand! With this divine artifact in hand, who dares face me in battle! #N, holding #G, sighed thus."
SpecailDesc0[25] = "Laugh at the Three Kingdoms, it lies in my pocket; speak of heroes — who under heaven besides me! With this divine artifact in hand, who dares face me in battle! #N, holding #G, sighed thus."

