LEVELHELP_TEXT1 = "^ff6fb3In-game security features:^ffffff\r^fedc40Safety Lock Feature^ffffff\rRecommended rating: ★★★★\rWhile Safety Lock is active, the following restrictions apply:\rCannot trade with other players, cannot stall, cannot sell, cannot destroy, cannot mail, cannot disassemble or enhance equipment, cannot operate Secret Text and Enchant Jade on equipment (embed, remove, transfer, socket and remove), cannot use equipment upgrade service, cannot perform item lock and unlock operations, cannot perform Gold Ingot trading operations (cannot deposit and withdraw, can purchase and sell Gold Ingots)\r\r"
LEVELHELP_TEXT2 = "^fedc40Item Lock Feature^ffffff\rRecommended rating: ★★★★★\rUse Tín Kim Toả on items to lock them. Once an item is locked, no operations can be performed: cannot destroy, trade, mail, or sell. This feature is very effective for protecting in-game items. We strongly recommend using this feature to enhance item security.\r\r"
LEVELHELP_TEXT3 = "^ff6fb3Game login protection features:^ffffff\r^fedc40Security Card Feature^ffffff\rRecommended rating: ★★★★\rSecurity Card is a simple and effective security feature. After linking a Security Card and enabling the service, you must combine it with the physical Security Card each time you log in. The password required for each login is different, which significantly enhances your account security.\r\r"
LEVELHELP_TEXT4 = "^fedc40Perfect Shield Feature^ffffff\rRecommended rating: ★★★★★\rPerfect Shield (Personal Key) is a hardware security device, convenient for users to use, and further protects user accounts from theft. Perfect Shield (Personal Key) uses a USB form factor, connecting to the computer's USB port. Through hardware means, it provides account protection. After a user's account is linked with Perfect Shield (Personal Key), every login to Perfect World game products will use this Perfect Shield (Personal Key). Its advantages are obvious: it can prevent account theft caused by Trojans, viruses, phishing, virtual phones, etc.\r\r"
LEVELHELP_TEXT5 = "^fedc40Account Safety Tips^ffffff\rWe strongly recommend you use the security features introduced above, and provide a few safety tips for your reference and use:\rStrengthen your computer system, regularly check for Windows updates to avoid OS vulnerabilities.\r1. Update firewall and antivirus software timely, regularly scan entire disk for viruses.\r2. Do not click or log into unfamiliar websites. All official activities and information will be announced on the sole official website of “Red Cliff”: ^fff962[http://chibi.wanmei.com](http://chibi.wanmei.com)^ffffff\r3. Do not go to unfamiliar or illegal internet cafes. Try to choose large, legitimate internet cafes to avoid account damage.\r4. Prevent others from peeking when entering account passwords. Pay special attention in crowded places like internet cafes.\r5. Change input order to make Trojans “useless”. Not entering passwords in normal order can prevent Trojans from recording keystrokes.\r6. Do not use unofficial third-party game software. These programs all contain Trojan viruses. They may seem to easily gain benefits but hide dangers. Officially, these third-party programs are strictly prohibited.\r7. Change your password regularly. If you use a Security Card, we recommend changing it once a month.\r8. Do not believe fake prize information from impersonated “system” staff or official releases. Prize information will be announced on the official website.\r9. Recognize the sole official website of “Red Cliff” ^fff962[http://chibi.wanmei.com](http://chibi.wanmei.com)^ffffff, do not log into event addresses provided by others. They may be fake phishing websites designed to steal your account or money.\r"
LEVELHELP_TEXT6 = ", congratulations on reaching Level 80! Please upgrade your ^7fffffPrimary Troop Type^ffffff to ^ff9090Venerable Stage Nine^ffffff, then you can petition #49145# to ascend to ^ff9090Hero Rank^ffffff, stepping onto a new glorious journey."
LEVELHELP_TEXT7 = ", congratulations on your Primary Troop Type reaching Venerable Stage Nine. You can now petition #49145# to ascend to Hero Rank, stepping onto a new glorious journey."
LEVELHELP_TEXT8 = "\rCurrent Primary Troop Type has not yet reached"
LEVELHELP_TEXT9 = "Stage Nine^e1e1e1.\r^fff600Note: Only after reaching Hero Rank can you receive the new experience type “Survival Experience Points”."
LEVELHELP_TEXT10 = "^e1e1e1When any Troop Type reaches ^ff9090Venerable Stage Nine^e1e1e1, you will receive the Hero Destiny. You can petition #49145# in Chang'an City to ascend to Hero Rank, stepping onto a new glorious journey."

LEVELTIP_TYPELIST = {"All", "Quest", "Guide", "Title"}
LEVELTIP_EventTips = "^fff600Qingming Hero Sacrifice\r^fff600Time:^ffffff April 4, 2011 - April 24, 2011\r^fff600Level:^ffffff 16+\r^fff600NPC: #71760#\r^ffffffAccept quest daily at Cloud City, go to Great Wu Temple and dialogue with Wu Qi. Then male characters can receive 2 “Clear Incense”, female characters can receive 2 “Willow Incense”, tradable. Prepare 1 “Clear Incense” and 1 “Willow Incense” to worship the Hero Spirit Monument. Can contact opposite gender to exchange items.\r\r^fff600Hero Sacrifice\r^fff600Time:^ffffff April 4, 2011 - April 24, 2011 (12:00 - 24:00)\r^fff600Level:^ffffff 16+\r^fff600NPC: #71760#\r^ffffffCan accept quest daily at Cloud City. Requires defeating Hero Lost Soul. Quest time limited to 1 hour. Team up for more efficient elimination!\r^fff600Note:^ffffff Hero Lost Soul will roam at Great Wu Temple, outside South Chang'an Gate, and inside Chang'an City, refreshing at random locations, not easy to find!\r\r^fff600Silk Butterfly Sends Yearning\r^fff600Time:^ffffff April 4, 2011 - April 24, 2011 (12:00 - 24:00)\r^fff600Level:^ffffff 16+\rPlayers with “Silk Butterfly” can release it at South Chang'an Gate. Players near the Silk Butterfly will receive a reward every 15 seconds, maximum 10 rewards per day!\rWhile waiting for rewards, everyone can chat, set off fireworks, make friends!! Who knows, fate might arrive right at this moment!\r\r^fff600One Cup Drunk Solves Thousand Worries\r^fff600Time:^ffffff April 4, 2011 - April 6, 2011 (18:00 - 24:00)\r^fff600Level:^ffffff 16+\r^fff600NPC: #71760#\r^ffffffCan receive Fine Wine “One Cup Drunk Solves Thousand Worries” at Cloud City. Time limited to 2 hours. Place this item in inventory, every 10 minutes you can receive a reward. Hero Rank players also have a chance to receive Chaos Divine Stone!!"
LEVELTIP_EventTips = "^fff600Red Cliff Troop's Heart\r^fff600Time:^ffffff April 25, 2011 - June 19, 2011\r^fff600Level:^ffffff 16+\r^fff600NPC: #71814#\r^ffffffComplete the Mysterious Hero Crystal quest to receive 1 Lucky Ticket! You can receive 1 per day!\rUse Lucky Tickets to exchange for rewards at Ha Tich Nhan — whatever reward you want, you can choose it yourself (yes)! No matter which reward you choose, you will also receive 1 Red Cliff Troop's Heart Ticket!\rFrom June 20 to July 3, you can use Red Cliff Troop's Heart Tickets to exchange for rewards at Ha Tich Nhan! 50 tickets can be exchanged for 100 Exquisite Micro Rings! 40 tickets can be exchanged for 67 Exquisite Micro Rings! 30 tickets can be exchanged for 33 Exquisite Micro Rings! Absolutely worth it!\r\r^fff600Challenge the God of War\r^fff600Time:^ffffff April 25, 2011 - June 19, 2011\r^fff600Level:^ffffff 16+\r^fff600NPC: #71811#\r^ffffffThere are even people impersonating the God of War! At Guan Yu's Mighty Eagle Cabin you can accept the quest — go and duel the one who calls himself “God of War” and see whether he still dares to use that title!!\r\r^fff600One Life, One Destiny\r^fff600Time:^ffffff May 16, 2011 - June 5, 2011 (18:00 - 23:59)\r^fff600Level:^ffffff 5+\r^fff600NPC: #71812#\r^ffffffYou can accept the Fate Comes to the Forest quest from Liu Xiaoyue and receive one kind of Destiny Bond status! Male and female players carrying different statuses form a party with the male as leader, then find Liu Xiaoyue to accept the “One Life, One Destiny” quest!\rCompleting the quest grants a bouquet of roses. Gift it to someone and they will receive 1 Fame Medal! Each person can only receive 1 Fame Medal per day! Up to 21 can be received during the event!\rCollect all 21 Fame Medals to exchange for the Limited Edition Rare Title at Ha Tich Nhan before July 3! You can also get a Great Completion Tome (Hero tier), 7 Exquisite Micro Rings (Hero tier), 3 Exquisite Gems (Hero tier 16 and above), Exquisite Fairies (Hero tier 31 and above), and tons of experience!!!\r^fff600Note: All rewards are guaranteed, not random! A rare chance — don't miss it!\r\r^fff600Let's Wrap Zongzi Together\r^fff600Time:^ffffff June 6, 2011 - June 19, 2011\r^fff600Level:^ffffff 16+\r^fff600NPC: #71949#\r^ffffffAccept the quest from Duan Xiaozong and receive a bomb! Defeat Ze Mo Xiaozei and use a bomb on him to instantly reduce his HP by 20%! If you are in a party, every member of the team can use a bomb on Ze Mo Xiaozei to kill it faster!! Invite your friends and family to take down Ze Mo Xiaozei together!\rDuring the event, completing Roaming the Dao Together, Challenge the God of War, or exchanging Lucky Tickets can each randomly yield a portion of Red Beans, Fresh Meat, or Red Dates — go to Duan Xiaozong to make some zongzi!"
--------------------------------------------------------------------
petst = {} ---Lời thoại nhàn rỗi
petst[1]="With my three lives of fire and smoke, I will trade for one fleeting lifetime of yours."
petst[2]="$name, you are peerlessly wise. I swear to follow you until I die!"
petst[3]="Fate cannot be fought, but destiny can be made. The weak accept fate, the strong defy it, the capable seek it, the wise create it."
petst[4]="The martial realm is in turmoil; I swear to advance and retreat together with you."
petst[5]="Roaming the world under wind and cloud is the aim of my life. Once step into the martial realm, the years and months urge me onward. Even talking and laughing among hegemons and kings is nothing compared to one bout of drunkenness in a lifetime."
petst[6]="$name, you are peerlessly wise. Whoever dares lay a hand on you must first get past me!"
petst[7]="Win and sing, lose and rest — sorrows and grudges are the same. Drink today and be drunk today; sorrow that comes tomorrow is for tomorrow."
petst[8]="In victory, no undue joy; in defeat, no undue fear. One with thunder in the heart and a calm lake on the face can achieve great things! $name, you are exactly that kind of person."
petst[9]="However long the road, every step can finish it; however short the road, you will never arrive without taking that first step. $name, let's stride forward together."
petst[10]="$name, shall we sit face to face and talk under the moon tonight?"
petst[11]="We plot for the world together — in fortune we share it, in calamity we bear it together. When there is porridge, we share the porridge; when there is none, we share the hunger!"
petst[12]="I could not share in your past, but I will walk beside you all the way into your future!"
petst[13]="One thought rises, and ten thousand rivers and mountains appear; one thought fades, and the blue sea turns to a mulberry field."
petst[14]="A few regrets, a few lifetimes of sorrow and joy — laughable that my fate is not mine to decide, but Heaven's."
petst[15]="One who cannot endure hardship is no hero; one never envied by others is a nobody."
petst[16]="Master, I'm hungry…"
petst[17]="Master, I haven't eaten meat for days…"
petst[18]="Master, I think I'm handsome again — that she-tiger keeps staring at me."
petst[19]="I have found that happiness is a matter of comparison — you need a baseline before you can feel it."
petst[20]="Life is like a game board. I vow to play my part well; my moves may be slow, but whoever meets me must still take a step back."
petst[21]="Our appointment stands, rain or shine."
petst[22]="$name, I fear water and cannot enter the naval battle at Red Cliff, but I can protect you through guard mode."
petst[23]="$name, if my reputation has not reached its maximum yet, you can use the Merit Book at the Whispers on Yun Terrace in Chang'an to raise my reputation."
petst[24]="The Glory Stone restores my Attack, Strategy, and HP, while the Metamorphosis Elixir restores my Martial, Intellect, and Constitution attributes — don't confuse the two!"
petst[25]="The Completion Tome can raise my current Morale by a certain amount."
petst[26]="If you wish to entrust me to another trustworthy person, you can use the Myriad Ages Brush at the Whispers on Yun Terrace in Chang'an to make me surrender, then hand my Surrender Letter to the person you wish to entrust me to."
petst[27]="The higher my reputation, the stronger my overall attributes, and the more likely the Metamorphosis Elixir is to grant higher innate talent."
petst[28]="There are some battlefields where I cannot be summoned, but I can protect you through guard mode."
petst[29]="When the National War is crowded and chaotic, I will not enter the fight, but I can protect you through guard mode."
petst[30]="The Devotion Reward Pack can raise my loyalty."
petst[31]="In passive mode, I will not attack enemies on my own, but if you or I am attacked, I will always strike back!"
petst[32]="In active mode, I will attack enemies within my sight on my own."
petst[33]="In rest mode, I will not attack any enemy."
petst[34]="Each point of Martial increases my Attack; the amount is determined by my Martial attribute."
petst[35]="Each point of Intellect increases my Strategy; the amount is determined by my Intellect attribute."
petst[36]="Each point of Constitution increases my HP; the amount is determined by my Constitution attribute."
petst[37]="Each time I gain a Level, I gain 3 free points!"
petst[38]="If others do not harm me, I harm no one. If they harm me once, I yield three parts in patience; if they harm me again, I return one thrust; if they still harm me, I pull the weed out by the root."
petst[39]="Either a magnificent funeral, or a single step up to heaven."
petst[40]="Rather than curry favor with others, better to arm myself. Rather than flee from reality, better to face life with a laugh. Rather than listen to wind and rain, better to raise my head and charge forth!"
petst[41]="Splendor is but a fleeting handful of sand; old age is but a stretch of years and months."
petst[42]="A traveler of the roads heeds the mandate of Heaven."
petst[43]="If a name can decide one's fate, I want to change my name to Qian Duoduo (Lots and Lots of Money)."
petst[44]="If others do not harm me, I harm no one. But if they harm me, I will be furious!"
petst[45]="I have found what they call a threshold: step through and it is a door; fail to step through and it becomes a barrier."
petst[46]="The proverb says ‘Silence is golden’ — so why have I been silent so long and still not become a rich man?"
petst[47]="Freedom is not doing whatever you want, but being able not to do what you don't want to do."
petst[48]="In favorable circumstances, act with calm composure; in adverse ones, act with detachment."
petst[49]="Ten thousand feet of red dust, three cups of wine; a thousand autumns of great enterprise, one pot of tea."
petst[50]="$name, when you collect your salary, take me to a tavern and order some good food!"
petst[51]="To learn to fight, you must first learn to take a beating."
petst[52]="One flower, one world; one leaf, one sword to seek. One song, one cry of sorrow; one lifetime, for one person."
petst[53]="$name is tired from walking — shall we find an inn to rest our feet? Just right, I'm a little hungry too…"
petst[54]="The scenery at Tinh Tru Pool in Tu Xien Valley is beautiful — if we have time, let's go see it!"
petst[55]="It's been a long time since I fought — time to get the muscles moving!"
petst[56]="Master, when do we go catch… er, no… steal a sheep?"
petst[57]="Follow $name and there's meat to eat!"
petst[58]="I think all the bears in the world are the same kind of bear."
petst[59]="It's cold out — $name, remember to dress warmly when you go out!"
petst[60]="Ask the blossom, and the blossom stays silent. For whom does it fall? For whom does it bloom? Of spring's charms, three parts in all — half borne by the flowing water, half lost to the dust."
petst[61]="As your guardian, I must have courage and dignity."
petst[62]="$name, how do you celebrate the New Year?"
petst[63]="The New Year passed so fast — I haven't had enough fun yet!"
petst[64]="$name, how are you feeling today?"
petst[65]="$name, be cheerful every day!"
petst[66]="Little white rabbit, white as white can be, loves turnips and greens, and hops about so adorably!"
petst[67]="Master, I want to eat turnips so badly!"
petst[68]="Master, master, Sister Heng is so beautiful! Have you met her yet?"
petst[69]="As a rabbit, I just have to carry a turnip! That way the pressure isn't so great!"
petst[70]="Master, I can't reach the turnip on my back — please help me!"
petst[71]="Master, actually I want to taste what meat is like too!"
petst[72]="Follow $name and there are turnips to eat!"
petst[73]="Master, I think I'm handsome again — that she-rabbit keeps staring at me."
petst[74]="You may not believe this, but Sister Heng once hugged me!"
petst[75]="When I was still a little bunny… I used to have a childhood sweetheart. Later on… never mind, I'll stop talking…"
petst[76]="Master, I saw someone whose guardian is a tiger — way too scary!"
petst[77]="Master, master, any turnips?"
petst[78]="Master, you're so tall!"
petst[79]="If the day ever comes that you pass through Changshan, Zilong will surely treat you to Hami melons and Yinhao tea."
petst[80]="Zilong swears to follow $name unto death."
petst[81]="I am someone who never holds a grudge — if I have a grudge, I settle it on the spot."
petst[82]="Some people are alive, yet they are dead; some people are alive, yet they should have died long ago."
petst[83]="What happens tomorrow or the day after, we'll find out soon enough."
petst[84]="Sword in hand and wine in cup, debating the realm — do not mistake lofty ambition for arrogance."
petst[85]="Yunchang swears to follow $name unto death."
petst[86]="Hadong is a fine place."
petst[87]="$name, do you know Hadong? That is Yunchang's homeland."
petst[88]="Just so, just like that…"
petst[89]="I am a mere martial artist, yet $name has treated me so generously. Yunchang would never betray such kindness!"
petst[90]="Master, I want to eat meat so badly!"
petst[91]="Grrrr…"
petst[92]="Master, I'm craving meat — when will you make me a few pieces?"
petst[93]="Master, I think I'm handsome again — that she-wolf keeps staring at me."
petst[94]="When I was still a little wolf… I used to have a childhood sweetheart. Later on… never mind, I'll stop talking…"
petst[95]="Don't judge me by my fierce appearance — I can be very gentle too!"
petst[96]="Master, take me out on a grand parade! Look how scared those people are — they don't dare come near me!"
petst[97]="I am a wolf from the North…"
petst[98]="Master, I heard someone's guardian is called the ‘Kaiming Tiger’ — I really want to meet one!"
petst[99]="Master, actually I could be good friends with the Star Rabbit and the Moon Rabbit… but they seem very afraid of me…"
petst[100]="With a bow in my hand, who can stop me!"
petst[101]="Whoever dares lay a hair on $name will answer to this old man's bow!"
petst[102]="$name, have you ever been to Nanyang? That is this old man's homeland…"
petst[103]="Nanyang's scenery is lovely — if $name ever gets the chance, you must go see it."
petst[104]="Everyone says this old man is peerlessly brave, and many young men cannot compare. What do you think?"
petst[105]="In this old man's heart, $name is forever the strongest!"
petst[106]="One roar from me and the enemy turns and flees!"
petst[107]="I, Zhang Yude, fear neither heaven nor earth!"
petst[108]="What I love most is lending a hand to the weak — ha ha ha!"
petst[109]="What I hate most is the way those hunting dogs use their power to bully others!"
petst[110]="Who dares touch $name! I won't allow it!"
petst[111]="$name, I want to drink…"
petst[112]="My clan? No one is left…"
petst[113]="Xiliang lies in a remote place, yet its golden sands stretch ten thousand miles, giving it a grandeur all its own."
petst[114]="Once I fought a man with a goatee wearing a red robe. I said, ‘Catch the one in red!’ and he threw off his robe. I said, ‘Catch the one with the goatee!’ and he cut off his beard…"
petst[115]="What lovely weather today!"
petst[116]="I'm not lying to you."
petst[117]="My stomach's growling…  gulp…"
petst[118]="What I hate most is this kind of lying."
petst[119]="What are you staring at? Are you a bumpkin?"
petst[120]="What shall I eat? I have to make a hard decision…"
petst[121]="News of the Spring Song, and so one gains eternal life."
petst[122]="Hmph! Why would I care about you?"
petst[123]="Resting for a whole day is never easy — the moment I wake up, it's time to sleep again."
petst[124]="Two tigers, two tigers, on a date, on a date — both of them male, both of them male! So perverted, so perverted…"
petst[125]="However grand a name you pick, in the end it loses to the name in the comment field."
petst[126]="I know you're very smart — 1+1=3, you get it"
petst[127]="I'm right here, so you'll never be without a home."
petst[128]="What happens tomorrow or the day after, we'll find out soon enough."
petst[129]="What an age this is — not even a hint of street-smart awareness…"
petst[130]="If I couldn't beat you, I would have turned on you long ago."
petst[131]="Words do not move the dead."
petst[132]="Ever since I went mad, my spirits have been much better."
petst[133]="I just suddenly feel a little bored — I'm not fooling anyone, heh."
petst[134]="Shh — whatever you do, don't tell them I did a good deed. It would ruin my image."
petst[135]="The trouble with chocolate is: once you eat it, there is none left."
petst[136]="Let me tell you a secret: someone who says ‘good night, I'm off to sleep’ is usually still bragging half an hour later."
petst[137]="A blurry world is the most lovable one!"
petst[138]="Have you heard the story ‘The big pig says yes, the little pig says no’??"
petst[139]="Every month always has 30 days when I don't want to read…"
petst[140]="Oh, am I made of candy? My legs have suddenly gone soft."
petst[141]="There is a hide-and-seek guild whose leader still hasn't been found."
petst[142]="I remember Chu Du in the year Little Qiao had just married him — so gallant and dashing. Feather fan and silk kerchief, laughing as he spoke, and an arrow struck his knee…"
petst[143]="(*^__^*) He he… Am I cute?"
petst[144]="Am I moe? Am I??"
petst[145]="When I have a son, I'll definitely name him Li Liang."
petst[146]="The sparrow is small, but when it plays, it plays with the whole sky."
petst[147]="When no one holds your hand, you can just slip it into your pocket."
petst[148]="They say everyone in this life will meet someone named Hua Niang. What about you?"
petst[149]="Do you like Zhuge Liang or Zhuge An (the Dark)?"
petst[150]="Did you know? Long ago Cao Cao wanted to encourage his soldiers, so he said there was a plum grove nearby and told everyone to hold out. Eventually they did find a water source, but the soldiers said: ‘No! We have to find that plum fruit…’ Poof."
petst[151]="Am I talking too much? They just like you, that's all O(∩_∩)O"
petst[152]="Rest, rest a little bit o(>﹏<)o"
petst[153]="Dong Zhuo's four great ideals: Lu Bu calls me ‘Father’ every day; the old man Wang Yun dies young. The tiny boat does not stage the Way of Nothingness; a hundred commoners of the Central Plains smile and greet me."
petst[154]="Cao Cao's four great ideals: All the people under heaven are named Cao; my army is so vast I need nothing more. Liu Bei no longer sings songs of opposition; Kongming becomes a fool tomorrow."
petst[155]="Sun Quan's four great ideals: The Great Qiao no longer troubles me; should Cao Cao come again, I will burn him. Guan Yu dies tomorrow; Jingzhou returns to my arms."
petst[156]="Liu Bei's four great ideals: Everyone under heaven speaks well of me; A Dou no longer plays the fool. Emperor Xian issues his edicts daily, ordering me to raise an army against Cao Cao."
petst[157]="Zhuge Liang's four great ideals: My wife, skilled with the knife, laughs in my dreams; the one who plays it cool must fan a feather fan. Wei Yan beats and breaks his bones every day; Sima becomes a great female demon."
petst[158]="Guan Yu's four great ideals: All the great generals under heaven fall to my blade; Sun Quan and Lu Meng come to my jail. Zhuge Tongfu is the one I laugh at, yet I must still help my elder brother restore the Han."
petst[159]="Chu Du's four great ideals: Kongming gets ridden away by me; Cao Ren breaks his back drawing a bow. Mengde falls into the grass when he meets disaster; the Son of Heaven sends me with troops to destroy and exterminate."
petst[160]="Zhang Fei's four great ideals: Everyone in the Three Kingdoms is a fool; Cao Cao flees the moment he sees me. Ma Chao is old as of tomorrow; my son is not a thing to be discarded."

petbt={} ---Lời thoại chiến đấu
petbt[1]="Under the boundless sky and earth, one sword cuts off every way of retreat. Where the splendor is, the sound of singing falls. Leaning on a thousand-layered cloud that veils my loneliness — let others laugh at me if they please."
petbt[2]="$name, if we win this battle, will you take me to the market to buy a hairpin?"
petbt[3]="I could slay him with one hand."
petbt[4]="Help! Someone's attacking me!"
petbt[5]="In my opinion, he's useless!"
petbt[6]="Aiya — tell him to stay away from me!"
petbt[7]="The good stuff comes later!"
petbt[8]="Too dangerous — I'll stand a bit further away then…"
petbt[9]="A wave of my hand kills a row; a push of my hand kills a heap."
petbt[10]="$name, if we win this battle, will you take me to the market to buy a jug of good wine?"
petbt[11]="He's no match for you — let me have a go at him!"
petbt[12]="You go first — I'll cover you!"
petbt[13]="Who dares anger you? I'll make him die in a most rhythmic fashion."
petbt[14]="Come here, and let the enemy see how fearsome I am!"
petbt[15]="Grrr!"
petbt[16]="Let me strike! Let the enemy see the wrath of me — the king of all beasts!"
petbt[17]="Master, if we win this battle, buy me more meat!"
petbt[18]="Just talking about him is not enough — I have to beat him myself before he learns I am skilled in both literary and martial arts."
petbt[19]="A scholar dies for the one who truly knows him."
petbt[20]="Seeing him, I suddenly thought of the pig I used to raise at home."
petbt[21]="Just let him ride his horse over here!"
petbt[22]="How dare he challenge you - does he want to die, or has he given up on living?"
petbt[23]="$name, watch out!"
petbt[24]="I'll beat him so that from now on he won't dare look you in the eye!"
petbt[25]="Let me finish him off with a stroke as swift as lightning, before you can even cover your ears - sneaking the bell with a clatter, taking no mercy, a world overflowing with love, you needn't argue!"
petbt[26]="Master, watch out!"
petbt[27]="Even a rabbit would go mad!"
petbt[28]="Enough talk - watch my sword!"
petbt[29]="Zilong is honey through and through; he vows to brave fire and bullets for $name."
petbt[30]="Don't worry, $name - Zhao Yun is here!"
petbt[31]="Don't worry, $name - Yunchang is here!"
petbt[32]="Guan Yu is here - prepare to die!"
petbt[33]="Yunchang vows to brave fire and bullets for $name!"
petbt[34]="Enough talk - watch my blade!"
petbt[35]="Come here! Let the enemy see my wrath - the Wolf of the North!"
petbt[36]="I bite! I scratch! I hit!"
petbt[37]="Watch how fierce I am!"
petbt[38]="I haven't eaten much meat lately - otherwise I could be even more fearsome!"
petbt[39]="Alive, I am a heap of meat; dead, I am a heap of dirt."
petbt[40]="Watch my Hundred-Step Yang Piercer!"
petbt[41]="Hmph, I can destroy him even without a bow!"
petbt[42]="Waaah ya ya ya ya ya!!!"
petbt[43]="I am Zhang Yide, the Swallow of Yan!"
petbt[44]="Don't worry, $name - Mengqi is here!"
petbt[45]="All troops, attack! Huh - where did everyone go?"
petbt[46]="Let him taste our Xiliang local specialty - that is to say, one Tiger-Head Spear thrust from Ma Mengqi!"
petbt[47]="The spear is the king of a hundred weapons, its changes too cunning to foresee. This fellow's martial arts are unbearably stiff - watch me toy with him."

