--Arena Guide
---------------------------------------------------------------------
FightGuide={}
--What Is the Arena
FightGuide[1] = {text="The Han dynasty declines and heroes rise; the realm is torn by endless war. Our generation is gifted beyond measure, and all of us hope to shine upon this stage of history. With eighteen kinds of weapons in hand, who can hold off a thousand single-handed, who can stand against ten thousand with no rival? Let us form war teams and test our martial arts, to see who truly is unmatched in the world.\rNow, every Sunday afternoon, an arena tournament will be held. All players who have reached Hero Level may take part in this event, forming war teams to compete in martial arts against the other participating teams. Through round after round of battle, they will vie for the final championship.\rAll players who take part in this event can not only sharpen their skills and prove their true strength, but will also receive generous rewards. Do not hesitate any longer - call your strongest allies to your side, weapons in hand, and join this event!"}
--How to Create a Battle Team
FightGuide[2] = {text="^ff6fb3Requirements:^ffffff\rFrom 0 o'clock Monday to 0 o'clock Saturday each week, any player ranked in the top 500 of the Personal Overall Rating Leaderboard who has reached Hero level is eligible to create an arena team.\r\r^ff6fb3Related NPC:^ffffff\rAt the West Market Training Ground in Chang'an, find Arena Team Envoy #72210# and register to create an arena team.\r\r^ff6fb3Recruiting Teammates:^ffffff\rOnce you have an arena team, you can recruit any player who has reached Hero level as a teammate, up to 9 people per team. \rMethod one: Right-click a player's portrait and select Recruit.\rMethod two: Use Recruit Teammate in the arena team control panel and enter the target's name.\rMethod three: Right-click a player's name in the chat window and select Recruit.\r\r^ff6fb3Disbanding an Arena Team:^ffffff\rOnly the team leader can use this feature. To disband an arena team, go to the West Market Training Ground in Chang'an, find Arena Team Envoy -#72210#, and select Disband Arena Team. Disbanding an arena team has a 7-day waiting period. During this time, the team leader can cancel this request at any time via the Cancel Arena Team Disband command on the arena team control panel. After 7 days, the arena team will be disbanded.\r"}
--How to Register for the Arena
FightGuide[3] = {text="^ff6fb3Requirements:^ffffff\rWhen the team leader is online, the team leader is responsible for queuing; when the team leader is offline, the vice leader handles the queue.\r\r^ff6fb3Registration Time:^ffffff\rSaturday 19:00 - Sunday 13:50, of which Saturday 19:00 - Sunday 13:00 is the normal registration period, and Sunday 13:00 - 13:50 is the strict registration period. During the strict registration period, any team with fewer than 3 members online will have its registration cancelled. The tournament officially begins at 14:00.\r\r^ff6fb3Related NPC:^ffffff\rAt the West Market Training Ground in Chang'an, find Arena Officer #72209#. Select Register for Arena.\r\r^ff6fb3About Queuing:^ffffff\rThe arena can accept a maximum of 128 teams. When the number of registered teams exceeds 128, the final 128 teams will be selected based on each team's overall rating and queue time.\r\r^ff6fb3Selecting Battle Members:^ffffff\rAfter successful registration, you can use Select Battle Members on the interface to mark players for battle, minimum 3 people, maximum 6 people. ^ff0000From 13 o'clock on Sunday until the tournament ends, at least 3 people must be online to participate in the tournament. Otherwise, participation eligibility will be cancelled.\r\r^ff6fb3Viewing the Bracket:^ffffff\rAfter 19:00 every Saturday, you can use the button on the right side of the screen to open View Bracket on the arena queue interface and see the final matchup situation.\rThe bracket lets you view each team's promotion situation and battle details. Note: During battle, press the U key to view battle details immediately.\r"}
--Arena Process
FightGuide[4] = {text="^ff6fb3Overall Procedure:^ffffff\rThe arena consists of 128 teams, with each round conducted as direct elimination. Through a total of 7 rounds of competition, the final championship is contested. Each round lasts 15 minutes. A team that receives a bye will win directly upon entering the arena and advance to the next round. \rWhen each round begins, the system will remind eligible teams to enter the arena, or you can do so via the Enter Arena button on the control panel.\r\r^ff6fb3Procedure of Each Round:^ffffff\rEach round of competition is further divided into 3 small games, each lasting a maximum of 4 minutes. When each game begins, both sides are teleported to the entry point with full health to conduct this game. Finally, the winning conditions determine which team advances to the next round.\r"}
--Win/Lose Conditions of the Tournament
FightGuide[5] = {text="^ff6fb3Win/Loss Conditions of Each Game:^ffffff\r1. Kill all opposing members, and that team wins this game.\r2. When each game's 4-minute time limit ends, if both sides still have surviving members, compare the two teams' banner health; the team with more health wins.\r3. If the banner health is still equal, compare the number of survivors; the team with more survivors wins.\r4. If none of the above conditions can determine the winner of this game, both teams are ruled to have lost.\r\r^ff6fb3Win/Loss Conditions of Each Round:^ffffff\r1. In each round of competition, if all opposing members leave the battlefield, our side wins.\r2. The team that first wins 2 games wins the round.\r3. When 3 games end, the team with more game wins wins.\r4. If 3 games still cannot determine a winner, both teams are ruled to have lost, and neither advances to the next round.\r"}
--Solo Arena Stats
FightGuide[6] = {text="^ff6fb3Viewing Your Own Arena Attributes:^ffffff\rUse the corresponding button on the character control panel to open the personal arena attributes control panel.\r\r^ff6fb3Viewing Another Player's Arena Attributes:^ffffff\rRight-click the opponent's portrait, click the Arena button, and view the other player's arena attributes control panel.\r\r^ff6fb3Attribute Explanations:^ffffff\r^fffd44Martial Prowess Value:^ffffff The current player's Martial Prowess value. This value is earned by participating in tournaments and is used to redeem rewards.\r^fffd44Personal Arena Rank:^ffffff The current player's personal arena rank. This can also be looked up via the leaderboard.\r^fffd44Personal Overall Rating:^ffffff The personal equipment overall rating value.\r^fffd44End-of-Week Victory Record:^ffffff The best result achieved in history when participating in the arena.\r^fffd44Total Kills:^ffffff The total number of enemies killed in the arena.\r^fffd44Total Win Rate:^ffffff The win rate when participating in the arena.\r^fffd44Total Battle Appearances:^ffffff The total number of times participating in the arena.\r^fffd44Total Wins:^ffffff The total number of wins when participating in the arena.\r^fffd44Total Losses:^ffffff The total number of losses when participating in the arena.\r^fffd44Arena Level:^ffffff The current personal arena level.\r^fffd44Level Title:^ffffff The personal arena title. Obtained when the personal arena level increases.\r^fffd44Current Experience:^ffffff The current personal arena experience, earned by participating in the arena.\r^fffd44Current Arena Team Name:^ffffff The name of the arena team the player is currently in.\r"}
--Team Arena Stats
FightGuide[7] = {text="^ff6fb3Viewing Team Attributes:^ffffff\rUse Team Attributes in the personal arena control panel or the Arena button on the interface.\r\r^fffd44Attribute Explanations:^ffffff\r^fffd44Arena Team Leader:^ffffff The name of this arena team's leader\r^fffd44Arena Team Rank:^ffffff The current rank of the arena team. This can also be looked up via the leaderboard.\r^fffd44Arena Team Level:^ffffff The current level of the arena team.\r^fffd44Arena Team Title:^ffffff The title of the arena team.\r^fffd44Team Overall Rating:^ffffff The overall rating of the team. This score is determined by the total score of the 6 people with the highest personal overall ratings. This score is also one of the criteria for determining the final registration grouping result.\r^fffd44Current Team Experience:^ffffff The current team experience, earned by participating in the arena.\r^fffd44Battle Team Member List:^ffffff Displays information about teammates in the battle team.\r^fffd44Edit Announcement:^ffffff Each arena team has its own announcement, which the team leader can edit and publish.\r^fffd44Recruit Teammate^ffffff: This button is used to recruit comrades by entering a name.\r^fffd44Remove Teammate:^ffffff The team leader can use this button to kick a player out of this team.\r^fffd44Appoint Vice Leader:^ffffff Select a vice leader. Each team has only one vice leader.\r^fffd44Dismiss Vice Leader:^ffffff Dismiss the selected vice leader.\r^fffd44Cancel Arena Team Disband:^ffffff During the arena team disband waiting period, you can use this button to cancel the disband request.\r^fffd44Leave Team:^ffffff Apart from the team leader, other members can click this button to leave this arena team.\r"}
--Rewards and Exchanges
FightGuide[8] = {text="^ff6fb3How to Receive Rewards:^ffffff\rEach time you participate in the arena, rewards will be automatically granted to the player based on the team's competition results. The higher the final rank, the richer the rewards received.\r\r^ff6fb3Reward Contents:^ffffff\rMartial Prowess Value: Points earned through the arena, used to redeem rewards.\rTitle: When the player's personal arena level increases, title rewards are granted, a symbol of strength.\rLife Experience: Experience required for leveling up.\rGold Ingots: Currency that can circulate in Red Cliff.\r\r^ff6fb3How to Redeem Rewards:^ffffff\rUsing the Martial Prowess Value earned, you can find Arena Team Merchant NPC #72211# at the West Market Training Ground in Chang'an to view and redeem rewards.\r"}
--Arena Leaderboard
FightGuide[9] = {text="^ff6fb3How to View:^ffffff\rUse the Leaderboard button on the toolbar to open it and select the Arena Leaderboard page.\r\r^ff6fb3Title Rewards:^ffffff\rThe top 5 players on the monthly Personal Arena Experience Leaderboard will receive title rewards.\r"}

