---------------------------------------------------------------------
--Related Arena of the Realm Guide
---------------------------------------------------------------------
GangGuide={}
--What Is the Arena of the Realm
GangGuide[1] = {text="^ff6fb3Explanation:^ffffff\rThe Arena of All Under Heaven is where players from different servers compete. Players from various servers can enter the Arena of All Under Heaven via the All Under Heaven Arena Teleport Envoy, Martial Saint (83,110) in the city of Chang'an.\r\r^ff6fb3Gameplay:^ffffff\rThe current Arena of All Under Heaven server includes many arena events: Haomeng Pass, where many players compete for resources; the Heroes' Gathering personal arena; and the Legion Arena Tournament organized by legion units.\r\rTo demonstrate the fairness of the arena, both the Heroes' Gathering battlefield and the Haomeng Pass battlefield currently apply a brand-new matchmaking feature to group participants. The Legion Arena Tournament is a large-scale event organized by legion units.\r\rWord has it that you, a devoted arena fan, have long been eager to test your strength, so hesitate no more and set out on the journey to conquer the Arena of All Under Heaven."}
--Matchmaking Feature
GangGuide[2] = {text="^ff6fb3Explanation:^ffffff\rThe purpose of the matchmaking feature is to allow players, when participating in PVP battlefields, to compete against players of roughly equivalent strength.\r\rWhen players queue to join a battlefield, the system will match and assign them to sides. When the number of players in the matchmaking queue reaches the battlefield's participant count, the matchmaking is completed and the battlefield opens. Currently, the battlefield participation modes that apply the matchmaking feature include team matchmaking, solo matchmaking, and unrestricted matchmaking.\r\rBoth the Heroes' Gathering and Haomeng Pass battlefields on the Arena of All Under Heaven apply the matchmaking feature for entry. The Heroes' Gathering battlefield uses a time-limited opening method; players conduct matchmaking duels within a fixed time window. This battlefield's mode is solo matchmaking, and participants must queue as individuals.\r\rHaomeng Pass is an open-all-day battlefield. Because it requires a relatively large number of participants, if the number of people in the matchmaking queue is insufficient to open the battlefield, the battlefield cannot open.\r\rPlayers are advised to organize into groups and join the battlefield during certain time windows, such as 9 AM - 11 AM and 3 PM - 5 PM. Haomeng Pass uses the unrestricted mode, and players can queue as individuals or as teams."}
--Legion Arena Tournament Rules
GangGuide[3] = {text="^ff6fb3Registration Requirements:^ffffff\rThe Legion Arena Tournament event opens ^ffff00every other week^ffffff. Each time it opens, the first week is the period when all legions race onto the leaderboard. In the second week, rankings will be determined based on the previous week's legion contribution increase leaderboard, and registration for the Legion Arena Tournament begins on Monday evening. The legion leaders of the top 100 legions on the leaderboard are eligible to register, and the first 32 registered legions advance to the group draw.\r\r^ff6fb3Registration and Competition Times for Each Round:^ffffff\rMonday 19:00-20:00 Registration\rTuesday 21:00-23:00 Round 1, 32 to 16\rWednesday 21:00-23:00 Round 2, 16 to 8\rThursday 21:00-23:00 Round 3, 8 to 4\rFriday 21:00-23:00 Round 4, 4 to 2\rSaturday 21:00-23:00 Round 5, Finals\r\rThe Legion Arena Tournament applies a single-match direct elimination format. After five rounds of competition, the final champion is selected. Legion members who participate in each match will receive corresponding rewards, as well as additional rewards upon promotion."}
--Legion Arena Battlefield Process
GangGuide[4] = {text="^ff6fb3Procedure:^ffffff\rIn the Legion Arena Tournament battlefield, each side can have 80 members enter. Within 120 minutes, destroy the opposing commander or deal the most damage to him to win the battlefield.\r\rThe main areas of the battlefield are the attack and defense bases of both sides and three central battle areas. Players on both sides can capture the three major camps in the battlefield by seizing flags, but capturing them does not generate score.\r\rPlayers capture the major camps to refresh the Cloud Ascent Chariot, which climbs the central Beacon Tower of the camp. Lighting the Beacon weakens various attributes of the opposing commander, thereby achieving the goal of destroying the opposing commander.\r\rThe Cloud Ascent Chariot travels from the main base of the capturing side to that major camp. Along the way, opposing players can destroy it to prevent the Cloud Ascent Chariot from reaching the Beacon Tower. Similarly, if the Cloud Ascent Chariot successfully reaches below the Beacon Tower, our side's elite soldiers hidden inside the Cloud Ascent Chariot will leap out to support our players in destroying the enemy.\r\rLighting the Beacon at different major camps weakens different attributes of the opposing commander, such as reducing attack power and increasing direct and indirect damage taken. Players can choose according to the situation.\r\rThe battlefield also has Warships traveling between the three major camps. Players can pilot them to transport our players for strategic deployment, enhancing cooperation and battlefield strategy between players."}
--Heroes' Gathering Rules
GangGuide[5] = {text="^ff6fb3Class Specialization:^ffffff\rEach time, a player can choose one main class to participate in the tournament. Once the first matchmaking is performed, the player's main class is locked in. When participating in the Heroes' Gathering this week, only the class locked in during the first matchmaking can be used. The locked-in class status will be displayed in the “Score Ranking Details” on the queue interface.\r\r^ff6fb3Competition Schedule:^ffffff\rThe competition procedure is divided into three rounds. Wednesday, Thursday, and Saturday are competition days, with one cycle taking every other week; the following week clears the previous week's competition results. The specific schedule is as follows\r1) Single-Server Qualifiers:\rThe competition opens Thursday evening 21:00-22:30. During this time, players queue as individuals and are matched with opponents by class. After successful matchmaking, a 1V1 competition is conducted.\rAfter 22:30, based on individual match win score points, the top 5 of each class on the single server are selected. The next day, when the cross-server opens, repechage tickets will be sent via mail.\r2) Cross-Server Repechage:\rThe competition opens Thursday evening 21:00-22:30. Players who received repechage tickets from each server, after entering the cross-server during the competition's open time, conduct matchmaking duels by class.\rAfter 22:30, based on match win score points, the top 1 of each class is selected. When the cross-server opens on Saturday, finals tickets will be sent via mail.\r3) Cross-Server Finals:\rThe competition opens Saturday evening 22:00-23:30. The top player of each class conducts unrestricted class matchmaking during this time. In the final championship match, each time there is a chance to encounter powerful opponents of different classes. After successful matchmaking, a 1V1 competition is conducted.\rAfter 23:30, the competition selects the champion, runner-up, and third place based on match win score points. The next day, when the cross-server opens, rewards will be sent to them via mail. Every other week, this competition procedure is repeated."}
--Heroes' Gathering Battlefield Process
GangGuide[6] = {text= "^ff6fb3Explanation:^ffffff\rEvery Monday, at the All Under Heaven Arena's Number One Martial Master #85961# in the city of Chang'an, tickets for the Heroes' Gathering tournament are distributed. After using a ticket, you can queue to participate in the tournament within the specified time. When player matchmaking is completed via the matchmaking feature, the battlefield opens. Players enter the battlefield to conduct 1V1 competitions. The tournament applies a best-of-three format, with the following win/loss rules:\r\r1. During the match, if one side's player dies, that side is ruled to have lost, and the opposing player's match win count increases by one.\r2. When the match time ends, if neither side's player has died, the accumulated damage taken is compared; the side that took more damage loses, and the opposing player's match win count increases by one.\r3. If none of the above conditions are met, both sides lose, and neither side's match win count increases.\r4. The person who wins two games is the final winner."}

--Heroes' Gathering Rewards and Exchanges
GangGuide[7] = {text="^ff6fb3How to Obtain Rewards:^ffffff\rEach time you participate in a match, both the winner and loser will receive a certain amount of All-Star Gathering Points. In the preliminaries on each server, the top 5 of each unit type will be selected; they will receive 100 All-Star Gathering Points and a ticket to the repechage. The system will send these via mail when the cross-server event opens on Thursday. In the cross-server All-Under-Heaven Arena repechage, the top 1 of each unit type will be selected; the first-place finisher will receive 200 All-Star Points and a ticket to the finals. The system will send these via mail when the cross-server event opens on Saturday. In the cross-server All-Under-Heaven Arena finals, the top 3 will be selected; they will receive 300 All-Star Points.\rHow to Exchange Rewards:\r     All-Star Gathering Points can be used to exchange for rewards. You can view detailed rewards at the #85961# All-Under-Heaven Arena Martial Master in Chang'an City."}
--Rewards and Exchanges
GangGuide[8] = {text="Null"}
--Arena Leaderboard
GangGuide[9] = {text="Null"}

