PetGuide = {}
PetGuide[1] = {text="^ff6fb3Disband Guard\r\r^ffffffYou can disband guards that are no longer needed. Disbanded guards will disappear permanently, so please use this carefully!\r\rIf your guard slots are insufficient but you don't want to disband, you can use guard dispatch, or convert unbound guards into Guard Contracts.\r\rYou can click the Disband button on the guard panel to disband a guard.\r\r", image="CB\\图片\\护卫指引图片\\指引遣散.tga"}
PetGuide[2] = {text="^ff6fb3Bind Guard\r\r^ffffffUnbound guards can be converted into Guard Contracts to trade with others, but cannot promote in official rank.\r\rBound guards cannot be converted into Guard Contracts, so they cannot be traded with others, but can promote in official rank.\r\rOnce bound, they cannot return to an unbound state.\r\rYou can click the Bind button on the guard panel to perform binding.\r\r", image="CB\\图片\\护卫指引图片\\指引绑定.tga"}
PetGuide[3] = {text="^ff6fb3Refine Guard\r\r^ffffffGuard aptitude is divided into eight grades: ^a8a8a8Inferior^ffffff, ^ffffffCommon^ffffff, ^72fe00Superior^ffffff, ^0184ffRare^ffffff, ^a800ffExceptional^ffffff, ^ff7d2fImmortal^ffffff, ^fff962Divine^ffffff, ^ff4ca4Perfect^ffffff.\r\rThe higher a guard's attribute aptitude, the greater their growth potential in that attribute.\r\rRefining a guard will change their aptitude, and the higher the guard's reputation, the greater the chance of obtaining higher aptitude.\r\r^00ff00Glory Stone^ffffff can cause the guard's attack, strategy, and vitality to re-roll, while ^00ff00Refining Pill^ffffff can cause the guard's martial aptitude, intellect aptitude, and physique aptitude to re-roll.\r\rYou can click the Refine button on the guard panel to enter the Refine interface.\r\r", image="CB\\图片\\护卫指引图片\\指引易筋.tga"}
PetGuide[4] = {text="^ff6fb3Train Guard\r\r^ffffffGenerally, guards can be divided into four types: ^8d76ffBalanced^ffffff, ^ff4ca4General^ffffff, ^40b4a0Strategist^ffffff, and ^ceff8aSupport^ffffff.\r\rBalanced guards will manifest different growth tendencies based on their varying aptitudes.\r\rYou can train your guard into a different type.\r\rAfter training, the guard's attributes, rating, and personality will change, while experience, level, official rank, reputation, attribute allocation plan, and morale status will remain unchanged.\r\rChoosing different guard training types may require different items.\r\rSome special guards have no other types and therefore cannot be trained.\r\rYou can use the relevant items at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience to perform training.\r\r", image="CB\\图片\\护卫指引图片\\指引训练.tga"}
PetGuide[5] = {text="^ff6fb3Convert Guard to Contract\r\r^ffffffA guard must be converted into a Guard Contract before it can be traded with others.\r\rAfter conversion, the guard's attributes will not change, and its name will revert to the original name when first obtained.\r\rBound guards cannot be converted.\r\rLocked guards must be unlocked before conversion.\r\rUnbound and unlocked guards can use the ^00ff00Myriad Ages Brush^ffffff at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience to perform the conversion.\r\r", image="CB\\图片\\护卫指引图片\\指引投诚.tga"}
PetGuide[6] = {text="^ff6fb3Lock Guard\r\r^ffffffLocked guards cannot be converted or disbanded, and unlocking requires entering the character's warehouse password.\r\rIf your currently selected guard is in a locked state, this service will automatically switch to the unlock service.\r\rIf you haven't set a warehouse password yet, you must set one before locking.\r\rUnlocking a guard has no waiting time.\r\rYou can use ^00ff00Crimson Seal^ffffff and ^00ff00Nüwa Stone^ffffff at #69417# in the Cloud Platform of Chang'an to lock and unlock guards.\r\r", image="CB\\图片\\护卫指引图片\\指引锁定.tga"}
PetGuide[7] = {text="^ff6fb3Reset Guard Attribute Points\r\r^ffffffIf you are unsatisfied with your guard's attribute point allocation, you can use Reset Guard Attribute Points to restore the attribute points allocated to martial might, intellect, and physique back into free attribute points.\r\rYou can use ^00ff00Eternal Water^ffffff at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience to perform the reset.\r\r", image="CB\\图片\\护卫指引图片\\指引洗点.tga"}
PetGuide[8] = {text="^ff6fb3Promote Guard Official Rank\r\r^ffffffGuards start at Ninth Rank. After that, each time a guard reaches level 100, they can promote.\r\rAfter promoting in official rank, the guard's attribute growth will be significantly increased, but level, current experience, and allocated attribute points will be reset to 0, while lost morale will be retained, current morale becomes 100 points, and 20 free attribute points are added.\r\rAfter promoting in official rank, the experience required to level up for each guard level will increase correspondingly, while the morale required to level up remains unchanged.\r\rThe higher the guard's current official rank, the more money and experience required to promote.\r\rBound guards that reach level 100 can promote in official rank at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience.\r\r", image="CB\\图片\\护卫指引图片\\指引晋升官阶.tga"}
PetGuide[9] = {text="^ff6fb3Increase Guard Reputation\r\r^ffffffGuard reputation is currently divided into six tiers: Unknown Talent, ^72fe00Slightly Known^ffffff, ^0184ffRenowned in One Region^ffffff, ^a800ffFamous Far and Wide^ffffff, ^ff7d2fIllustrious Name Spreads Far^ffffff, ^fff962Renowned Across the Four Seas^ffffff.\r\rThe higher the guard's reputation, the stronger their overall attributes, and the greater the chance of obtaining higher aptitude during Refining.\r\rEach reputation increase can add 1 reputation point to the guard, and there is also a certain probability of directly promoting the guard's reputation to the next tier. Upon direct promotion, the guard's current reputation value will return to 0.\r\rWhen a guard's reputation reaches the maximum value of the current tier, the next reputation increase will definitely raise the guard's reputation by one tier.\r\rGuard reputation will not change due to other operations such as guard training or official rank promotion.\r\rGuards whose reputation has not reached the maximum tier can use ^00ff00Merit Register^ffffff at #69417# in the Cloud Platform of Chang'an with a certain amount of money to increase reputation.\r\rNinth Rank guards at the highest official position can only reach Famous Far and Wide.", image="CB\\图片\\护卫指引图片\\指引提高声望.tga"}
PetGuide[10] = {text="^ff6fb3Guard Skills\r\r^fffd441. Learn Guard Skill:^ffffff\r\rThrough the learn skill service, guards can comprehend new skills and become more powerful.\r\rLearning a skill requires the corresponding Skill Book. The effect of the learned skill will be displayed in the frame on the right side of the interface.\r\rSkill Books can be obtained by participating in events, quests, etc.\r\rSome skills have special restrictions: melee guards cannot learn skills restricted to ranged, and vice versa.\r\rLearned skills cannot be learned again.\r\rSkill effects can be enhanced through the “Upgrade Skill” service.\r\rYou can use the relevant items at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience to learn skills.\r\r^fffd442. Upgrade Guard Skill:\r\r^ffffffUpgrading a skill can enhance the effect of a learned skill.\r\rDrag the skill you want to upgrade into the corresponding frame under “Skill,” and the corresponding frame under “Required Items” will automatically fill with the items needed to upgrade that skill.\r\rSkill upgrade items can be obtained by participating in quests, events, etc.\r\rYou can use the relevant items at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience to perform the upgrade.\r\r^fffd443. Forget Guard Skill:\r\r^ffffffThrough the forget skill service, you can remove unwanted skills.\r\rYou can use ^00ff00Memory-Lost Incense^ffffff at #69417# in the Cloud Platform of Chang'an with a certain amount of money to perform the forgetting.\r\r", image="CB\\图片\\护卫指引图片\\指引技能学习.tga"}
PetGuide[11] = {text="^ff6fb3Guard Inheritance\r\r^ffffffGuard inheritance transfers a portion of one guard's (the donor) attributes to another guard (the recipient), using different items to transfer different attributes. Both the donor and recipient must be bound, and the donor's official rank must not be lower than Eighth Rank.\r\r^fffd44 1. Level Inheritance:\r\r^ffffffWhen using ^00ff00Heaven-Bestowed Pill^ffffff, the donor's official rank and level will be transferred to the recipient. Requires the donor's official rank to be higher than the recipient's, or the same official rank but higher level.\r\rAfter inheritance, the donor's official rank returns to Ninth Rank, and their level, all attribute points, lost morale, and current experience are reset to 0; current morale becomes 100 points. The recipient inherits the donor's official rank, level, attribute allocation status, lost morale, and current experience; current morale remains unchanged.\r\r^fffd44 2. Reputation Inheritance:\r\r^ffffffWhen using ^00ff00Heaven-Piercing Stone^ffffff, the donor's reputation tier and aptitude ratings will be transferred to the recipient. Requires the donor's reputation tier to not be lower than the recipient's.\r\rAfter inheritance, the donor's reputation tier returns to Unknown Talent, reputation value becomes 0, and all aptitude ratings are reset; the recipient inherits the donor's reputation tier, reputation value, and aptitude ratings.\r\r", image="CB\\图片\\护卫指引图片\\指引技能升级.tga"}
PetGuide[12] = {text="", image="CB\\图片\\护卫指引图片\\指引技能遗忘.tga"}
PetGuide[13] = {text="^ff6fb3Guard Morale System\r\r^ffffffA guard's morale state will have a certain effect on their overall attributes.\r\r^fffd441. Current Morale:^ffffff\r\rEach time a guard levels up, a certain amount of current morale is consumed.\r\rWhen current morale is higher than the morale required to level up, the guard will receive bonus attributes upon leveling up; when current morale is insufficient for the guard to level up, the morale deficit will be counted toward lost morale.\r\rWhen training a guard, current morale does not change; when promoting in official rank, current morale becomes 100 points.\r\rYou can use ^00ff00Triumph Book^ffffff to increase a guard's current morale, with an upper limit of 1000 points.\r\r^fffd442. Morale Required to Level Up:^ffffff\r\rCurrent morale consumed when a guard levels up.\r\rThe higher the guard's level, the more morale required to level up.\r\r^fffd443. Lost Morale:^ffffff\r\rWhen current morale is insufficient for the guard to level up, the morale deficit will be counted toward lost morale.\r\rYou can use ^00ff00Medal of Honor^ffffff to increase a guard's lost morale.\r\r", image="CB\\图片\\护卫指引图片\\指引士气系统.tga"}
PetGuide[14] = {text="^ff6fb3Detailed Guard Attribute Explanation\r\r^fffd441. Command Value:^ffffff\r\rYou can purchase guard-related items in the Command Value Shop.\r\rCan be obtained in the Gathering of Worthies event.\r\r^fffd442. Guard Reputation:^ffffff\r\rGuard reputation is currently divided into six tiers: Unknown Talent, ^72fe00Slightly Known^ffffff, ^0184ffRenowned in One Region^ffffff, ^a800ffFamous Far and Wide^ffffff, ^ff7d2fIllustrious Name Spreads Far^ffffff, ^fff962Renowned Across the Four Seas^ffffff.\r\rThe higher the guard's reputation, the stronger their overall attributes, and the greater the chance of obtaining higher aptitude during Refining.\r\rGuards whose reputation has not reached the maximum tier can use ^00ff00Merit Register^ffffff at #69417# in the Cloud Platform of Chang'an with a certain amount of money to increase reputation.\r\r^fffd443. Binding:^ffffff\r\rUnbound guards can be converted into Guard Contracts to trade with others, but cannot promote in official rank.\r\rBound guards cannot be converted into Guard Contracts, so they cannot be traded with others, but can promote in official rank.\r\rOnce bound, they cannot return to an unbound state.\r\rYou can click the Bind button on the guard panel to perform binding.\r\r^fffd444. Lock:^ffffff\r\rLocked guards cannot be converted or disbanded, and unlocking requires entering the character's warehouse password.\r\rIf you haven't set a warehouse password yet, you must set one before locking.\r\rUnlocking a guard has no waiting time.\r\rYou can use ^00ff00Crimson Seal^ffffff and ^00ff00Nüwa Stone^ffffff at #69417# in the Cloud Platform of Chang'an to lock and unlock guards.\r\r^fffd445. Rarity:^ffffff\r\rGuard rarity currently has five types: Ordinary Aptitude, ^72fe00Hard to Find at High Price^ffffff, ^0184ffOnce in a Hundred Years^ffffff, ^a800ffOnce in a Thousand Years^ffffff, ^ff7d2fOne in Ten Thousand^ffffff.\r\rThe higher the guard's rarity, the better their overall attributes.\r\rRarity is an innate attribute of the guard and currently cannot be changed.\r\r^fffd446. Level:^ffffff\r\rThe guard's current level, maximum 100.\r\rBound guards that reach level 100 can promote in official rank, after which the level returns to 0.\r\rWhen leveling up a guard, current experience and current morale will be consumed.\r\r^fffd447. Official Rank:^ffffff\r\rGuards start at Ninth Rank. After that, each time a guard reaches level 100, they can promote.\r\rAfter promoting in official rank, the guard's attribute growth will be significantly increased, but level, current experience, and allocated attribute points will be reset to 0, while lost morale will be retained, current morale becomes 100 points, and 20 free attribute points are added.\r\rAfter promoting in official rank, the experience required to level up for each guard level will increase correspondingly, while the morale required to level up remains unchanged.\r\rBound guards that reach level 100 can promote in official rank at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience.\r\r^fffd448. Loyalty:^ffffff\r\rWhile a guard is summoned to battle or in guard state, the guard's loyalty will decrease when the guard or the player dies. The higher the guard's level, the more loyalty decreases.\r\rWhen loyalty equals 0, the guard cannot be summoned to battle.\r\rWhen loyalty is below 100, the guard cannot enter guard state.\r\rWhen loyalty is above 100, the guard's critical hit rate will be enhanced.\r\rCan be replenished by using Merit Reward Packs.\r\r^fffd449. Current Experience and Experience Required to Level Up:^ffffff\r\r^00fffcGain Experience^ffffff\r\rWhen the guard is in guard state or summoned to battle, regardless of whether the owner completes daily activities or the owner or guard kills monsters, both the owner and guard can receive the same experience and survival experience as well as dropped items.\r\rThe greater the level difference between monsters killed and the owner, the less experience received.\r\rKilling certain special monsters will not grant experience.\r\r^00fffcAccumulated Experience^ffffff\r\rThe accumulated experience limit for guards before level 60 is 2 times the experience required to reach level 60. For guards level 60 and above, the accumulation limit is 2 times the experience required for the current level.\r\rWhen the guard's experience equals or exceeds the above limit, no more experience will be gained, and experience-boosting items cannot be used on them.\r\r^fffd4410. Skill Slots:^ffffff\r\rThe guard's usable skills will be displayed in the skill slots.\r\rUnopened skill slots can be opened by using the relevant items.\r\r^fffd4411. Vitality:^ffffff\r\rWhen in guard state, it will be added to the owner's vitality at a certain ratio.\r\rCan view aptitude ratings in the guard's Refine interface.\r\rThe guard's vitality recovers faster when recalled, recovers slower when deployed, and does not recover in guard state.\r\rIf you want to recover quickly, you can use guard HP recovery items.\r\r^fffd4412. Attack Power:^ffffff\r\rWhen in guard state, it will be added to the owner's additional damage at a certain ratio.\r\rCan view aptitude ratings in the guard's Refine interface.\r\r^fffd4413. Strategy:^ffffff\r\rEvery 2 points of strategy will increase the guard's additional damage by 1 point.\r\rWhen in guard state, it will be added to the owner's healing power at a certain ratio.\r\rCan view aptitude ratings in the guard's Refine interface.\r\r^fffd4414. Three Aptitudes:^ffffff\r\rMartial aptitude affects the attack power gained per point of martial might.\r\rIntellect aptitude affects the strategy gained per point of intellect.\r\rPhysique aptitude affects the vitality gained per point of physique.\r\rCan view aptitude ratings in the guard's Refine interface.\r\r^fffd4415. Growth Tendency:^ffffff\r\rThere are three growth tendencies in total: ^ff4ca4General Type^ffffff, ^40b4a0Strategist Type^ffffff, and ^ceff8aSupport Type^ffffff.\r\rA guard's growth tendency is the direction in which they have the greatest development potential.\r\rFor example, a General-type guard will gain more attack power per level up and per point of martial might allocated.\r\r^fffd4416. Martial Might, Intellect, Physique:^ffffff\r\rYou can freely allocate remaining points to these three attributes.\r\rEach point of martial might increases attack power; the increase amount is determined by martial aptitude.\r\rEach point of intellect increases strategy; the increase amount is determined by intellect aptitude.\r\rEach point of physique increases vitality; the increase amount is determined by physique aptitude.\r\rIf you are unsatisfied with the allocation, you can use ^00ff00Eternal Water^ffffff at #69417# in the Cloud Platform of Chang'an with a certain amount of money and character experience to reset the points.\r\r^fffd4417. Remaining Points:^ffffff\r\rEach time a guard levels up, 3 free points are added.\r\rAfter a guard promotes in official rank, all allocated and unallocated points are cleared, and 20 free points are added per promotion.\r\r^fffd4418. Aptitude Points:^ffffff\r\rComprehensive total from the aptitude ratings of six attributes: attack power, strategy, vitality, martial aptitude, intellect aptitude, and physique aptitude.\r\rThe growth tendency aptitude rating carries a larger weight in the comprehensive total.\r\rYou can use Refining on the guard to re-roll; guards with higher reputation have a greater chance of obtaining higher aptitude points.\r\r^fffd4419. Core Aptitude:^ffffff\r\rAptitude rating on the guard's growth tendency; the more stars, the better the guard's aptitude in that growth tendency.\r\rFor example, a General-type guard with higher core aptitude stars has better aptitude in attack power and martial aptitude.\r\r^fffd4420. Growth Potential:^ffffff\r\rA guard's growth potential will overall affect the growth of their attack power, strategy, and vitality upon each level up and each attribute point allocation.\r\rThe higher the guard's reputation, the higher the official rank, the higher the growth potential stars.\r\r^fffd4421. Morale:^ffffff\r\rA guard's morale state will have a certain effect on their overall attributes.\r\r^fff600Current Morale:^ffffff\r\rEach time a guard levels up, a certain amount of current morale is consumed.\r\rWhen current morale is higher than the morale required to level up, the guard will receive bonus attributes upon leveling up; when current morale is insufficient for the guard to level up, the morale deficit will be counted toward lost morale.\r\rWhen training a guard, current morale does not change; when promoting in official rank, current morale becomes 100 points.\r\rYou can use ^00ff00Triumph Book^ffffff to increase a guard's current morale, with an upper limit of 1000 points.\r\r^fff600Morale Required to Level Up:^ffffff\r\rCurrent morale consumed when a guard levels up.\r\rThe higher the guard's level, the more morale required to level up.\r\r^fff600Lost Morale:^ffffff\r\rWhen current morale is insufficient for the guard to level up, the morale deficit will be counted toward lost morale.\r\rYou can use ^00ff00Medal of Honor^ffffff to increase a guard's lost morale.\r\r^fffd4422. Personality:^ffffff Guard personality is divided into five types: Valiant, Agile, Wise, Fervent, Focused. The sum of these five personalities is 100%; every guard simultaneously possesses all five personalities, only with slightly different tendencies.\r\r^00fffcValiant:^ffffff\rSpirit that swallows all, sweeping a thousand armies like a scroll. Tendency to increase the guard's own attack power and limit the enemy's attack power.\r\r^00fffcAgile:^ffffff\rAgile footwork, leaving enemies unable to react. Tendency to weaken the enemy's damage resistance, control resistance, seal resistance, weaken resistance, and bleed resistance.\r\r^00fffcWise:^ffffff\rDivine calculation, wisdom beyond others. Tendency toward healing power and influence on healing effectiveness against enemies.\r\r^00fffcFervent:^ffffff\rFull of passion, advancing despite difficulties. Tendency toward the guard's own critical hits and influence on enemy critical hits.\r\r^00fffcFocused:^ffffff\rConcentrated mind, focused on subduing enemies. Tendency to limit defense and indirect resistance against enemies.\r\r", image="CB\\图片\\护卫指引图片\\指引属性详细.tga"}
PetGuide[15] = {text="^ff6fb3Guardian Combat\r\r^fffd441. Guardian Combat Modes:^ffffff\r\rGuardian combat modes are divided into Summon to Battle and Guardian.\r\r^00fffcSummon to Battle:^ffffff\r\rOnce the Guardian is summoned to battle, it has three combat modes—Active, Passive, and Rest.\r\rIn Active mode, the Guardian will actively attack enemies within its sight range;\r\rIn Passive mode, the Guardian will not actively attack enemies, but will automatically counterattack when attacked, and will support its master in attacking enemies;\r\rIn Rest mode, the Guardian will not attack any enemy.\r\r^00fffcGuardian:^ffffff\r\rIn Guardian state, the Guardian does not appear directly, but instead adds its own attributes to the player by a percentage.\r\rThe Guardian's attack power is added as bonus damage for the player;\r\rThe Guardian's tactics are added as healing points for the player;\r\rThe Guardian's HP is added to the player's HP.\r\r^fffd442. Guardian and Player vs Player Combat:^ffffff\r\rA Guardian in Summon to Battle state deals 30% damage to players; the Guardian's attribute bonuses for the player in Guardian state will not be reduced during PK\r\r^fffd443. Restrictions on Summoning Guardians to Battle:^ffffff\r\rCertain maps and battlefields prohibit summoning Guardians to battle; when a Guardian is summoned, it will automatically enter Guardian state.\r\r^00fffcMaps prohibiting Guardian Summon to Battle:^ffffff\r\r^ff80ffNational War Map  Red Cliff Naval Battle Map  Army Training Grounds^ffffff\r\r^00fffcBattlefields prohibiting Guardian Summon to Battle:^ffffff\r\r^ff80ffHorse Racing Arena  Sun Xiang's Tale  Demon Realm Ranking  Market Lyra  Loulan Ancient Palace  Eight Formation Illusion Map^ffffff\r\r", image="CB\\图片\\护卫指引图片\\指引护卫战斗.tga"}

--------------------------------------------------------------------
--Battlefield guide text content, in the interface file BattleGuide.xml
--BattleGuide[X]：X is the script template ID
--903：Eight Trigrams Formation — Open Gate
--905：Eight Trigrams Formation — Open Gate Leader
--------------------------------------------------------------------
BattleGuide = {}
BattleGuide[903] = {
	{text = "Step One: Collect treasure chests to receive ^0078f0Monster Jade^3a1f01.\r\r\rNotes:\r1. Monster Jade can be traded, but will disappear when leaving the battlefield.\r2. Besides next to Huang Chengyan, certain stages will also drop treasure chests.\r3. In the next 3 stages, planting money trees can produce treasure chests.", image = "CB\\图片\\战场指引图\\八阵开门1.tga"},
	{text = "Step Two: Use Monster Jade to buy ^0078f0Mechanism Spirit Parts^3a1f01 at the stone statue.\r\r\rNotes:\r1. Mechanism Spirit Parts disappear when leaving the battlefield.\r2. Each time you clear a stage, the stone statue will have new parts for sale.", image = "CB\\图片\\战场指引图\\八阵开门2.tga"},
	{text = "Step Three: Use Mechanism Spirit Parts to turn the ^0078f0Eight Formations Banner^3a1f01 into a mechanism, and attack the charging enemy army.\r\rNotes:\r1. Clear the stage by killing all enemies; if the guardian stone statue dies, you fail.\r2. If you fail, you can challenge the current stage again.\r3. Give one Monster Jade to an activated mechanism to dismantle it.", image = "CB\\图片\\战场指引图\\八阵开门3.tga"},
	{text = "Additional notes:\r1. Each stage has 4 waves of invading enemies; each wave's arrival is signaled by a flag.\r2. You can clear up to 4 stages in a row: Good Stage, Scholar Stage, Cannon Stage, and General Stage.\r3. Each stage cleared grants life experience rewards.\r4. After clearing 4 stages, the fewer failures, the better the reward.\r5. Each stage has 2 invading enemy factions, and you will randomly enter one of them.", image = ""}
}
BattleGuide[905] = {
	{text = "Step One: Collect treasure chests to receive ^0078f0Monster Jade^3a1f01.\r\r\rNotes:\r1. Monster Jade can be traded, but will disappear when leaving the battlefield.\r2. Besides next to Huang Chengyan, certain stages will also drop treasure chests.\r3. In the next 3 stages, planting money trees can produce treasure chests.", image = "CB\\图片\\战场指引图\\八阵开门1.tga"},
	{text = "Step Two: Use Monster Jade to buy ^0078f0Mechanism Spirit Parts^3a1f01 at the stone statue.\r\r\rNotes:\r1. Mechanism Spirit Parts disappear when leaving the battlefield.\r2. Each time you clear a stage, the stone statue will have new parts for sale.", image = "CB\\图片\\战场指引图\\八阵开门2.tga"},
	{text = "Step Three: Use Mechanism Spirit Parts to turn the ^0078f0Eight Formations Banner^3a1f01 into a mechanism, and attack the charging enemy army.\r\rNotes:\r1. Clear the stage by killing all enemies; if the guardian stone statue dies, you fail.\r2. If you fail, you can challenge the current stage again.\r3. Give one Monster Jade to an activated mechanism to dismantle it.", image = "CB\\图片\\战场指引图\\八阵开门3.tga"},
	{text = "Additional notes:\r1. Each stage has 4 waves of invading enemies; each wave's arrival is signaled by a flag.\r2. You can clear up to 4 stages in a row: Good Stage, Scholar Stage, Cannon Stage, and General Stage.\r3. Each stage cleared grants life experience rewards.\r4. After clearing 4 stages, the fewer failures, the better the reward.\r5. Each stage has 2 invading enemy factions, and you will randomly enter one of them.", image = ""}
}
--Battlefield guide for Chariot Formation·Peerless Chariot
BattleGuide[947] = {
	{text = "^dd006fBattlefield Guide^3a1f01\r\rWelcome to “Chariot March·Invincible War Chariot”. This battlefield guide not only introduces in detail every aspect of Red Cliff's newly released PVP battlefield, but also explains how to use war chariots. This guide includes the following two parts:\r\rOne、Battlefield Strategy\rTwo、War Chariot Introduction\r\rNote: You can click the “Battlefield Guide” button in the lower-left corner at any time to view this guide.", image = "CB\\图片\\战车指引图\\封面.tga"},
	{text = "^dd006fBattlefield Strategy^3a1f01\r\r1, Capture mine points to gain resources\rAfter battle begins, you can capture the iron mine and sulfur mine; once a mine point is captured, all players on your side will periodically receive resources.\r2, Capture chariot construction sites to obtain war chariots\r^00b800West Mountain Fort^3a1f01 and ^00b800East Lake Iron Furnace^3a1f01 are captured the same way; after capturing the flag, they will sequentially produce two ^a800ffNight Hawk^3a1f01 and ^a800ffDivine Engineer^3a1f01. ^00b800Wind and Fire Platform^3a1f01 requires defeating the guard commander first; after the Wind and Fire Platform flag appears, capturing it can produce two ^e66700Heavenly Soldier^3a1f01.", image = "CB\\图片\\战车指引图\\战场攻略.tga"},
	{text = "^3a1f013, Destroy enemy structures\rDestructible structures include ballista towers, gateside barricades, outer city ballista towers, central ballista towers, the central crystal, and the in-city war chariot manager. Among them:\r•The gateside archer guards are invincible until the barricade is destroyed;\r•The outer city ballista tower is invincible until the corresponding gateside ballista tower is destroyed;\r•Once any outer city ballista tower is destroyed, the central ballista tower loses its invincibility;\r•Only after both central ballista towers are destroyed can the central crystal be attacked.", image = "CB\\图片\\战车指引图\\战场攻略.tga"},
	{text = "^3a1f014, Achieve Victory\rThe battlefield uses a points system. Destroying enemy structures grants accumulated points. Destroying the enemy central crystal ends the battlefield immediately. If time runs out and neither side's central crystal has been destroyed, victory, defeat, or draw is decided by both sides' accumulated points.", image = "CB\\图片\\战车指引图\\战场攻略.tga"},
	{text = "^dd006fObtaining Resources^3a1f01\r\rBattlefield resources are divided into two types: iron mines and sulfur mines. They can be obtained in the following ways:\r1, Complete the ^e66700Battlefield Guide^3a1f01 quest and the ^0184ffGlorious Merit^3a1f01 quest;\r2, Capture iron mine and sulfur mine points; all members of your side can periodically receive resources. Capturing an iron mine point yields 3 iron ore per minute, and a sulfur mine point yields 1 sulfur ore per minute;\r3, The first time a mine point is captured, nearby players can receive a resource reward;", image = "CB\\图片\\战车指引图\\战场资源.tga"},
	{text = "^3a1f014, Kill enemy players and soldiers;\r5, Open treasure chests that appear after capturing the Wind and Fire Platform;\r6, In addition, all players receive a fixed amount of resources every minute.", image = "CB\\图片\\战车指引图\\战场资源.tga"},
	{text = "^dd006fDriving War Chariots^3a1f01\r\rThere are 5 types of war chariots in the battlefield. Each side can drive up to 14 war chariots; new war chariots will not be produced until the old ones are destroyed.\r\r^0184ffTiger King^3a1f01\rProduction location: Our side's main base\rResources consumed: 48 Iron Ore, 16 Sulfur Ore\r^0184ffHou Yi^3a1f01\rProduction location: Our side's main base\rResources consumed: 48 Iron Ore, 16 Sulfur Ore", image = "CB\\图片\\战车指引图\\封面.tga"},
	{text = "^a800ffNight Hawk^3a1f01\rProduction location: West Mountain Fort\rResources consumed: 30 Iron Ore, 10 Sulfur Ore\r^a800ffDivine Engineer^3a1f01\rProduction location: East Lake Iron Furnace\rResources consumed: 30 Iron Ore, 10 Sulfur Ore\r^e66700Heavenly Soldier^3a1f01\rProduction location: Wind and Fire Platform\rResources consumed: 72 Iron Ore, 24 Sulfur Ore", image = "CB\\图片\\战车指引图\\封面.tga"},
	{text = "^dd006fBattlefield Rewards^3a1f01\r\rIn the battlefield you can obtain “^00b800War Chariot Honor Points^3a1f01”, which can be exchanged for battlefield rewards at the War Chariot Altar. “^00b800War Chariot Honor Points^3a1f01” can be obtained in the following ways:\r1, Complete the ^ffffffFirst Victory^3a1f01 quest (2 points)\r2, Be the first to capture a mine point or chariot construction site (1 point)\r3, Be the first to destroy a gateside ballista tower (1 point)\r4, Be the first to destroy an outer city ballista tower (1 point)\r5, Be the first to destroy a central ballista tower (1 point)\r6, Win the battlefield (4 points)", image = "CB\\图片\\战车指引图\\战场物品.tga"},
	{text = "^3a1f017, Bring 2 “Campaign Orders” and complete the battlefield (4 points)\r8, Bring 2 “Campaign Orders” and 1 “Death River Pearl” and complete the battlefield (15 points)", image = "CB\\图片\\战车指引图\\战场物品.tga"},
	{text = "^dd006fWar Chariot Introduction^3a1f01\r\rThis section introduces the war chariot driving interface, controls, skill usage, and war chariot types, etc.\rWar chariots are powerful weapons of war. The Chariot March battlefield has 5 types of war chariots in total, including 4 single-rider chariots and 1 multi-rider chariot. They are:\r^0184ffTiger King^3a1f01、^0184ffHou Yi^3a1f01、^a800ffNight Hawk^3a1f01、^a800ffDivine Engineer^3a1f01、^e66700Heavenly Soldier^3a1f01", image = "CB\\图片\\战车指引图\\封面.tga"},
	{text = "^dd006fWar Chariot Driving Interface^3a1f01\r\rAfter successfully obtaining a war chariot, you will immediately board it, and the war chariot driving interface will appear. From left to right:\rSkills: 4 skills in total\rInvite: The Heavenly Soldier driver can use this function to invite other players to board\rDismount: Click to dismount. For multi-rider chariots, if the driver dismounts, everyone dismounts.", image = "CB\\图片\\战车指引图\\战车驾驶界面.tga"},
	{text = "^dd006fWar Chariot Controls^3a1f01\r\rMove forward/backward: Use the ^00b800W^3a1f01 and ^00b800S^3a1f01 keys on the keyboard to move\rTurn left/right: Use the ^00b800A^3a1f01 and ^00b800D^3a1f01 keys on the keyboard to turn, or drag with the right mouse button to turn\rAttack: Click an attack skill, or use the corresponding shortcut keys ^3a1f011~4^3a1f01", image = "CB\\图片\\战车指引图\\战车操控.tga"},
	{text = "^dd006fWar Chariot Skills^3a1f01\r\rEach type of war chariot has up to 4 skills. War chariot skills are the key indicator distinguishing chariot characteristics. Among them:\rSkill 1: Normal attack skill. You can right-click the skill icon to put it in ^00b800auto-use state^3a1f01; right-click again to cancel this state.\rSkill 4: Finishing skill. It deals very heavy damage, but has a correspondingly longer cooldown.", image = "CB\\图片\\战车指引图\\战车技能.tga"},
	{text = "^dd006fWar Chariot Restrictions^3a1f01\r\rWhile on a war chariot, certain functions are prohibited:\r•Cannot use original skills\r•Cannot use any items\r•Cannot set up a stall, lean on each other, duel, use action emotes, or trade\r•Multi-rider chariots cannot teleport\r•Cannot use guardians and war souls", image = "CB\\图片\\战车指引图\\战车限制.tga"},
	{text = "^0184ffTiger King^3a1f01 \rSingle-rider chariot\rA powerful melee chariot with thick armor; a reliable core force.\r\rFirepower: ^ffffffNormal^3a1f01\rRange: ^ff0000Very Short^3a1f01\rArmor: ^00b800Very High^3a1f01\rMobility: ^ffffffNormal^3a1f01\r\rSkills:\rDragon Flame Bullet, Swallow Return Strike, Repel Strike, Twin Volley Shot", image = "CB\\图片\\战车指 dẫn图\\虎王.tga"},
	{text = "^0184ffHou Yi^3a1f01 \rSingle-rider chariot\rHas excellent ranged attack capability; its weakness is slow speed and vulnerability.\r\rFirepower: ^00b800Excellent^3a1f01\rRange: ^00b800Very Long^3a1f01\rArmor: ^ff0000Quite Weak^3a1f01\rMobility: ^ff0000Quite Poor^3a1f01\r\rSkills:\rRapid Shot, Crippling Shot, Volley Shot, Heaven's One Strike", image = "CB\\图片\\战车指引图\\后羿.tga"},
	{text = "^a800ffNight Hawk^3a1f01 \rSingle-rider chariot\rHas outstanding mobility unmatched by other chariots, excels at surprise attacks.\r\rFirepower: ^ffffffNormal^3a1f01\rRange: ^ff0000Very Short^3a1f01\rArmor: ^ffffffNormal^3a1f01\rMobility: ^00b800Very Strong^3a1f01\r\rSkills:\rFlying Slash, Twin Wing Strike, Yang Wing Slash, Eight Direction Wind Dance", image = "CB\\图片\\战车指引图\\夜鹰.tga"},
	{text = "^a800ffDivine Engineer^3a1f01 \rSingle-rider chariot\rThe only chariot with recovery and support capabilities; the darling of the battlefield.\r\rFirepower: ^ff0000Very Poor^3a1f01\rRange: ^ffffffNormal^3a1f01\rArmor: ^ff0000Quite Weak^3a1f01\rMobility: ^ffffffNormal^3a1f01\r\rSkills:\rDrum Dance, Inspiring Drum, Burning Blood, Inspiring Charge", image = "CB\\图片\\战车指引图\\神工.tga"},
	{text = "^e66700Heavenly Soldier^3a1f01 \rMulti-rider chariot\rThe supreme weapon that can carry 3 people at once; powerful in all aspects.\r\rFirepower: ^00b800Excellent^3a1f01\rRange: ^00b800Quite Long^3a1f01\rArmor: ^00b800Very High^3a1f01\rMobility: ^ffffffNormal^3a1f01\r\rDriver skill: Vanguard Charge\rGunner skills: Volley, Chain Volley, Crippling Volley, Divine Wind Precision Shot", image = "CB\\图片\\战车指引图\\天兵.tga"},
}
--Battlefield guide for Chariot Test Drive·Sand Sea Cavalry
BattleGuide[948] = {
	{text = "^dd006fWar Chariot Guide^3a1f01\r\rWelcome to the War Chariot Guide. In this guide, we will introduce the war chariot driving interface, controls, skill usage, and war chariot types, etc.\rWar chariots are powerful weapons of war. To experience war chariots, you can go to the Test Drive War Chariot·Desert Sea Wonder Soldiers battlefield and the newly released Chariot March·Invincible War Chariot battlefield.\rIf you have questions about war chariots and battlefields, you can click the Battlefield Guide button in the lower-left corner at any time to view help.", image = "CB\\图片\\战车指引图\\封面.tga"},
	{text = "^dd006fWar Chariot Driving Interface^3a1f01\r\rAfter successfully obtaining a war chariot, you will immediately board it, and the war chariot driving interface will appear. From left to right:\rSkills: 4 skills in total\rInvite: The Heavenly Soldier driver can use this function to invite other players to board\rDismount: Click to dismount. For multi-rider chariots, if the driver dismounts, everyone dismounts.", image = "CB\\图片\\战车指引图\\战车驾驶界面.tga"},
	{text = "^dd006fWar Chariot Controls^3a1f01\r\rMove forward/backward: Use the ^00b800W^3a1f01 and ^00b800S^3a1f01 keys on the keyboard to move\rTurn left/right: Use the ^00b800A^3a1f01 and ^00b800D^3a1f01 keys on the keyboard to turn, or drag with the right mouse button to turn\rAttack: Click an attack skill, or use the corresponding shortcut keys ^3a1f011~4^3a1f01", image = "CB\\图片\\战车指引图\\战车操控.tga"},
	{text = "^dd006fWar Chariot Skills^3a1f01\r\rEach type of war chariot has up to 4 skills. War chariot skills are the key indicator distinguishing chariot characteristics. Among them:\rSkill 1: Normal attack skill. You can right-click the skill icon to put it in ^00b800auto-use state^3a1f01; right-click again to cancel this state.\rSkill 4: Finishing skill. It deals very heavy damage, but has a correspondingly longer cooldown.", image = "CB\\图片\\战车指引图\\战车技能.tga"},
	{text = "^dd006fWar Chariot Restrictions^3a1f01\r\rWhile on a war chariot, certain functions are prohibited:\r•Cannot use original skills\r•Cannot use any items\r•Cannot set up a stall, lean on each other, duel, use action emotes, or trade\r•Multi-rider chariots cannot teleport\r•Cannot use guardians and war souls", image = "CB\\图片\\战车指引图\\战车限制.tga"},
	{text = "^0184ffTiger King^3a1f01 \rSingle-rider chariot\rA powerful melee chariot with thick armor; a reliable core force.\r\rFirepower: ^ffffffNormal^3a1f01\rRange: ^ff0000Very Short^3a1f01\rArmor: ^00b800Very High^3a1f01\rMobility: ^ffffffNormal^3a1f01\r\rSkills:\rDragon Flame Bullet, Swallow Return Strike, Repel Strike, Twin Volley Shot", image = "CB\\图片\\战车指 dẫn图\\虎王.tga"},
	{text = "^0184ffHou Yi^3a1f01 \rSingle-rider chariot\rHas excellent ranged attack capability; its weakness is slow speed and vulnerability.\r\rFirepower: ^00b800Excellent^3a1f01\rRange: ^00b800Very Long^3a1f01\rArmor: ^ff0000Quite Weak^3a1f01\rMobility: ^ff0000Quite Poor^3a1f01\r\rSkills:\rRapid Shot, Crippling Shot, Volley Shot, Heaven's One Strike", image = "CB\\图片\\战车指引图\\后羿.tga"},
	{text = "^a800ffNight Hawk^3a1f01 \rSingle-rider chariot\rHas outstanding mobility unmatched by other chariots, excels at surprise attacks.\r\rFirepower: ^ffffffNormal^3a1f01\rRange: ^ff0000Very Short^3a1f01\rArmor: ^ffffffNormal^3a1f01\rMobility: ^00b800Very Strong^3a1f01\r\rSkills:\rFlying Slash, Twin Wing Strike, Yang Wing Slash, Eight Direction Wind Dance", image = "CB\\图片\\战车指引图\\夜鹰.tga"},
	{text = "^a800ffDivine Engineer^3a1f01 \rSingle-rider chariot\rThe only chariot with recovery and support capabilities; the darling of the battlefield.\r\rFirepower: ^ff0000Very Poor^3a1f01\rRange: ^ffffffNormal^3a1f01\rArmor: ^ff0000Quite Weak^3a1f01\rMobility: ^ffffffNormal^3a1f01\r\rSkills:\rDrum Dance, Inspiring Drum, Burning Blood, Inspiring Charge", image = "CB\\图片\\战车指引图\\神工.tga"},
	{text = "^e66700Heavenly Soldier^3a1f01 \rMulti-rider chariot\rThe supreme weapon that can carry 3 people at once; powerful in all aspects.\r\rFirepower: ^00b800Excellent^3a1f01\rRange: ^00b800Quite Long^3a1f01\rArmor: ^00b800Very High^3a1f01\rMobility: ^ffffffNormal^3a1f01\r\rDriver skill: Vanguard Charge\rGunner skills: Volley, Chain Volley, Crippling Volley, Divine Wind Precision Shot", image = "CB\\图片\\战车指引图\\天兵.tga"},
}

--Heroes 11 Xu Chu Story
BattleGuide[950] = {
	{text = "^dd006fSelect Difficulty^3a1f01\rHaomeng Pass battlefield applies a new resource point capture method: when the number of survivors from one side in the resource point area exceeds the other side, the capture bar begins to move; when it reaches the end, that side captures successfully. When both sides have equal numbers, the capture bar pauses until one side regains the numerical advantage.", image = "CB\\图片\\战场指引图\\许褚传1.tga"},
	{text = "^dd006fHidden 5-Star Difficulty Challenge^3a1f01\r　　1、After successfully challenging any 1 battle in the previous 4-star difficulties of Xu Chu's Tale, there is a chance to receive the “Xu Chu's Tale Mysterious Ticket”; this item is the key to unlocking 5-star difficulty.\r　　2、After selecting 5-star difficulty, the challenge quest NPC—Ma Chao will appear; talk to him, and using the “Xu Chu's Tale Mysterious Ticket” you can unlock the hidden stage.\r　　3、When selecting 5-star difficulty, the team must have at least one player who owns the “Xu Chu's Tale Mysterious Ticket” to complete this challenge quest.", image = "CB\\图片\\战场指引图\\许褚传2.tga"},
}

--Heroes Gan Ning Story
BattleGuide[952] = {
	{text = "^dd006f1、Low-difficulty stages and hidden stages^3a1f01\rThis challenge, after the 2-minute preparation ends, will randomly open one of 4 low-difficulty stages for the player team to challenge; if the hidden stage quest is accepted, the hidden stage challenge will open.\r^dd006f2、Transition animation guide^3a1f01\rAll stages of “Gan Ning's Tale” this time take place on three ship hulls; after the 2-minute wait ends, the path the player team needs to take will be guided by different opening animations.\r", image ="CB\\图片\\战场指引图\\甘宁传1.tga"},
	{text = "^dd006f3、Hidden stage challenge^3a1f01\rAfter clearing any stage among the 4 randomly selected low-difficulty stages of “Gan Ning's Tale”, there is a chance to receive the “Gan Ning's Tale Mysterious Ticket”; carrying this item, you can accept the hidden difficulty challenge quest from Zuo Ci.\rAfter accepting the quest, the challenge quest NPC—Gan Ning will appear; talk to him, and using the “Gan Ning's Tale Mysterious Ticket” you can unlock the hidden stage.\rThe team must have at least one player who owns the “Gan Ning's Tale Mysterious Ticket” to proceed with this challenge quest.", image = "CB\\图片\\战场指引图\\甘宁传2.tga"},
}

--Heroes Huang Zhong Story
BattleGuide[1007] = {
	{text = "^dd006f1、How to play Lightfoot^3a1f01\rHuang Zhong's Tale this time introduces the concept of a Lightfoot dungeon. Lightfoot controls: activate the key combination, double-tap “w” to enter Lightfoot state; after using the jump key, the character will perform a triple jump. After flying a distance, the player lands; at this point Lightfoot can be used again.\rThis dungeon closely combines the BOSS fight mechanics with Lightfoot characteristics, allowing players to instantly dodge BOSS attacks through Lightfoot and prevent the BOSS from escaping. Experience a new style of dungeon gameplay.\r", image ="CB\\图片\\战场指引图\\黄忠传1.tga"},
	{text = "^dd006f2、Low-difficulty stages and hidden stages^3a1f01\rThis challenge, after the 2-minute preparation ends, will randomly open one of 4 low-difficulty stages for the player team to challenge; if the hidden stage quest is accepted, the hidden stage challenge will open.", image = "CB\\图片\\战场指引图\\黄忠传2.tga"},
	{text = "^dd006f3、Hidden stage challenge^3a1f01\rAfter clearing any stage among the 4 randomly selected low-difficulty stages of “Huang Zhong's Tale”, there is a chance to receive the “Huang Zhong's Tale Mysterious Ticket”.\rAfter selecting 5-star difficulty, the challenge quest NPC—Huang Zhong will appear; talk to him, and using the “Huang Zhong's Tale Mysterious Ticket” you can unlock the hidden stage.\rThe team must have at least one player who owns the “Huang Zhong's Tale Mysterious Ticket” to proceed with the 5-star difficulty challenge.", image = "CB\\图片\\战场指引图\\黄忠传3.tga"},
}

--Cross-Server Battlefield Haomeng Pass
BattleGuide[1009] = {
	{text = "^dd006f1、Capture method^3a1f01\rHaomeng Pass battlefield applies a new resource point capture method: when the number of survivors from one side in the resource point area exceeds the other side, the capture bar begins to move; when it reaches the end, that side captures successfully. When both sides have equal numbers, the capture bar pauses until one side regains the numerical advantage.\r", image ="CB\\图片\\战场指引图\\葭萌关1.tga"},
	{text = "^dd006f2、Capture Resource Points^3a1f01\rCentral resource points provide 1.5 times the accumulated points of the surrounding resource points. They also refresh the Supply Wagon for extra accumulated points. Besides providing points, the Armory and Seven Star Altar resource points also affect the pontoon bridge and the weather. In addition, the buff points that periodically refresh at random on the battlefield also affect victory or defeat to some degree.", image = "CB\\图片\\战场指引图\\葭萌关2.tga"},
	{text = "^dd006f3、Defeat Enemies^3a1f01\rDefeating or assisting in defeating enemy players both award Haomeng Pass Merit points. In addition, achieving first blood, killing ten enemies, and winning the battlefield all grant large amounts of Merit. After the battlefield ends, you can exchange Merit for battlefield titles and other special rewards at the Grand General NPC.", image = "CB\\图片\\战场指引图\\葭萌关3.tga"},
}


--Cross-Server Battlefield Haomeng Pass Time-Limited
BattleGuide[1068] = {
	{text = "^dd006f1、Capture method^3a1f01\rHaomeng Pass battlefield applies a new resource point capture method: when the number of survivors from one side in the resource point area exceeds the other side, the capture bar begins to move; when it reaches the end, that side captures successfully. When both sides have equal numbers, the capture bar pauses until one side regains the numerical advantage.\r", image ="CB\\图片\\战场指引图\\葭萌关1.tga"},
	{text = "^dd006f2、Capture Resource Points^3a1f01\rCentral resource points provide 1.5 times the accumulated points of the surrounding resource points. They also refresh the Supply Wagon for extra accumulated points. Besides providing points, the Armory and Seven Star Altar resource points also affect the pontoon bridge and the weather. In addition, the buff points that periodically refresh at random on the battlefield also affect victory or defeat to some degree.", image = "CB\\图片\\战场指引图\\葭萌关2.tga"},
	{text = "^dd006f3、Defeat Enemies^3a1f01\rDefeating or assisting in defeating enemy players both award Haomeng Pass Merit points. In addition, achieving first blood, killing ten enemies, and winning the battlefield all grant large amounts of Merit. After the battlefield ends, you can exchange Merit for battlefield titles and other special rewards at the Grand General NPC.", image = "CB\\图片\\战场指引图\\葭萌关3.tga"},
}

--Cross-Server War
BattleGuide[1036] = {
	{text = "^3a1f01\rThe cross-server battlefield is won by defeating the enemy commander, but both sides' commanders start with very high stats and are hard to bring down.\r\rBy burning the beacon pyres on the high platforms at the three central battlefield points, you can progressively reduce three types of the enemy commander's stats. The enemy commander, weakened by low morale, will become vulnerable and much easier to defeat.\r", image ="CB\\图片\\战场指引图\\跨服战场1.tga"},
	{text = "^3a1f01\rThe three high platforms at the three central battlefield points cannot be climbed directly. Both sides must fight for the flags in the battlefield points to gain area control.\r\rAfter successfully pulling up the area-control flag, that side's base will refresh a Cloud Ladder heading toward the corresponding high platform. Watch out for enemy players destroying the Cloud Ladder along the way. When the Cloud Ladder reaches its destination it becomes invincible; quickly climbing the new Cloud Ladder is the way onto the platform to light the beacon pyres.", image = "CB\\图片\\战场指引图\\跨服战场2.tga"},
	{text = "^3a1f01\rRavaged by war, the fortresses have completely changed — the earthen walls and ramparts are gone, so the central battlefield points and the eastern and western camps can no longer connect. Travel is only possible via Warships along the riverbank. A Warship can carry only 10 people at a time. Remember the Warship docking points and use them well to achieve a surprising tactical advantage.", image = "CB\\图片\\战场指引图\\跨服战场3.tga"},
}

