--------------------------------
--Official Rank System Help
--------------------------------
PositionHelp = "^ff6fb3Detailed Explanation of the Official Rank System:^ffffff\r\r^ff6fb3Level 10^ffffff：\rJoin as a Recruit at #2484#; joining as a Recruit requires first completing the “Receive Rank - Recruit” quest. The quest-giving NPC is #3270#.\r\r^ff6fb3Level 20^ffffff：\rWhen your Merit reaches 50, promote to Military Rank - Soldier at #2485#.\r\r^ff6fb3Level 30^ffffff：\rWhen your Merit reaches 100, promote to Military Rank - Sergeant at #2219#.\r\r^ff6fb3Level 40^ffffff：\rReceive the guidance quest at #2488# and choose the Civil Official Path (requires 200 Civil Merit) or the Military Official Path (requires 200 Military Merit).\rFor Civil Officials, find #2490#; for Military Officials, find #2489#. You can then obtain the “Nine-Rank Official” title.\rAfter that, you can collect your daily official salary from these two NPCs, and be promoted to a higher rank once the conditions are met.\rUpon promotion you receive the corresponding Official Title, granting permanent stat boosts. With an Official Title, you can also take part in Daily Official Quests to earn more Civil or Military Merit. After reaching a high official rank, you can purchase Official Seal Treasures with powerful stats.\r\r^fffd44Level 40——receive from #7339#\rLevel 44——receive from #7340#\rLevel 46——receive from #7118#\rLevel 50——receive from #7126#\rLevel 53——receive from #6820#\rLevel 57——receive from #6837#^ffffff\r\rConditions for the next promotion:\r\r^ff6fb3Level 50^ffffff：\rWhen your Merit reaches 600, you can promote to the Eighth Rank.\r\r^ff6fb3Level 60^ffffff：\rWhen your Merit reaches 2000, you can promote to the Seventh Rank.\r\rFrom the Sixth Rank upward there are many official types, and players can choose freely.\r\r^ff6fb3After Level 60^ffffff, to raise Civil and Military Merit you must go to the faction leaders of Wei, Shu, and Wu. Take Daily Official Quests or Imperial Edict quests to earn them. Note, however, that you must be Level 61 to enter the faction leader cities."

--------------------------------
--Activity Points Explanation
--------------------------------
HelpEvent2 = "1, In the event, members can work together to earn Activity Points for the Legion. “Grain Transport” accumulates 1 point each time, “Bandit Suppression” accumulates 2 points each time, and defeating an “Enemy Raider” accumulates 5 points.\r\r2, When the Activity Points reach ^00ff40500^ffffff, a vegetable thief appears and the grain wagon departs. Legion members can join forces to defeat the vegetable thief.\r\r3, When the Activity Points reach ^00ff40800^ffffff, the grain wagon returns. Legion members can divide up the work, voluntarily choosing “Grain Transport” or “Bandit Suppression”.\r\r4, When the Activity Points reach ^00ff401000^ffffff, “Enemy Raiders” appear and gradually close in on the Legion Vegetable Harvest Officer, who will be killed by them. Use “Fire Mines” to deal with the Enemy Raiders.\r\rFire Mine\rBound on pickup\rRequires Level 1\rAn item that helps everyone deal with Enemy Raiders.\rPlayers Level 1-80, and female players of any level, can receive 1 per day from the ^fff600Legion Vegetable Harvest Officer^ffffff.^fff600\rEach time this item is thrown at an Enemy Raider, it loses 50% of its HP!^ffffff\r\rNote: Legion members Level 1-80, and female members of any level, can receive 1 “Fire Mine” per day from the Legion Vegetable Harvest Officer.\r\r5, When the Activity Points reach ^00ff401500^ffffff, Xue Mei (-49, 76 in our base) appears. The Commander, Deputy, and Activity Manager can choose which war general to challenge.\rThe war generals are divided into 5 tiers with different difficulties; choose carefully based on your Legion's strength. You can challenge only once per day.\r\r6, When the Activity Points reach ^00ff401000^ffffff, ^00ff402000^ffffff, and ^00ff403000^ffffff, to thank everyone for their efforts, Reward Messengers will appear in turn to deliver rewards to all Legion members. Members inside the Legion base will receive the rewards automatically."


--------------------------------
--Five Tiger Generals expansion announcement, text used for pathfinding
--------------------------------
Board1 = "#72209#"
Board2 = "Receive the North Mang Expedition Order at #27047#, then you can set out on the expedition."
Board3 = "At #72211# and others, you can exchange rich rewards for the points you accumulated by taking part in the tournament!"


--------------------------------
--Character Trading Description Text
--------------------------------
TradeCharGuide =
{
	"^ff6fb31. Character Sale Conditions^ffffff\rTo sell a character, the following conditions must be met:\r^fffd44◆Level no lower than Hero 1\r◆If you hold a Sworn Brotherhood leader position, you must first transfer it to someone else\r◆If you hold a Legion Leader position, you must first transfer it to someone else\r◆You must not have a Master-Apprentice relationship\r◆You must not be on an Arena team\r◆Your account or character must not be banned or muted\r◆You must leave any cross-server Arena Legion\r^ffffff\r\r^ff6fb32. Registering a Character^ffffff\rFirst, the seller must choose “Register this character for sale” with me. We will check whether the character meets the sale conditions; if not, you will receive the appropriate notice. Once all sale conditions are met, the character enters the registration period, which lasts 7 days.\rDuring the registration period the character can play normally, and the character will appear as “Registered” on your character selection list. If you wish to cancel the registration, you can come back to me at any time and choose “Cancel character registration” to end the sale registration.\r\r^ff6fb33. Selling a Character^ffffff\rAfter the 7-day registration period has passed, you can formally sell your character through me. If you do not choose “Sell Character” within the 3-day buffer period, the character's registration status will be cancelled automatically.\rWhen you choose “Sell Character” and the conditions are verified as met, the character formally enters the “Display Period”. You will automatically return to the character selection screen, where the character appears as “For Sale”.\r\r^ff6fb34. Display Period^ffffff\rCharacters in the “Display Period” are frozen and cannot log in. During this time you can view display-period characters on the official Xunbao Tianxing consignment page for Red Cliff. The Display Period lasts 3 days.\rUpon entering the Display Period, messages will be sent to the following relationships to notify them that your character has gone up for sale:\r^fffd44◆Sworn Brotherhood and Legion members who are online receive an online message\r◆The corresponding spouse receives a mail notification\r◆Friends receive a mail notification^ffffff\r\r^ff6fb35. Sale Period^ffffff\rAfter the 3-day Display Period, if no appeals or reports have been received, the character enters the formal tradable “Sale Period”. Once in the Sale Period, the character can be sold through Xunbao Tianxing. However, if the character is never purchased, then after the Sale Period ends the website will automatically cancel the sale, and you will be able to log in and use the character in game shortly afterward.\r^fffd44Total consignment period = buffer period + display period + sale period^ffffff. The buffer period is the 3 days counted from the end of the registration period; the Display Period is the 3 days counted from when “Sell Character” is chosen; the formal Sale Period is up to 7 days counted from the end of the Display Period. Therefore the total consignment period is at most ^fffd443+3+7=13^ffffff days.\r\r^ff6fb36. Cancelling Consignment^ffffff\rA character in the consignment period always appears as “For Sale” on the character selection screen. During this time, if you wish to cancel the consignment, you must first log in to the Red Cliff Xunbao Tianxing homepage and manually take the character down, then cancel the consignment on the character selection screen by clicking the “Cancel Consignment” button next to the character.",
"To purchase a character, the buyer must log in to the Red Cliff Xunbao Tianxing page, browse the characters for sale under the “Character” category, then designate a “character to be overwritten” under the buyer's account to complete the purchase.\rMost of the seller character's attributes will transfer to the buyer's “character to be overwritten”, while attributes that are not overwritten remain unchanged. After the transaction ends, the seller character will also undergo some processing.\r\r^ff6fb31. Preparing the Buyer's Character^ffffff\rFirst the buyer must have a character in game. This character is called the “character to be overwritten” and must meet the following conditions:\r^fffd44◆Level no higher than 15\r◆Total money in bag and warehouse must not exceed 5 Jade\r◆Total items in bag must be fewer than 10\r◆The warehouse must contain no items\r◆Gender must match the purchased character\r◆Race is unrestricted (it will be overwritten)^ffffff\rThrough the official Xunbao Tianxing webpage, browse the “Character” products, select the character you want to purchase, and designate one overwritable character under your own account. The system will then check whether that character meets the conditions above; if it does, the purchase succeeds.\r\r^ff6fb32. Attribute Transfer^ffffff\rMost of the seller character's attributes will transfer to the buyer's “character to be overwritten”, but a small portion will be retained. The same applies to the buyer's character: most attributes will be overwritten, while some are retained.\rAttributes retained by the seller character include:\r^fffd44◆Character name\r◆Gender, race\r◆Friends, enemies\r◆Sworn Brotherhood, Legion, spouse\r◆Consumption points, Legion and Sworn Brotherhood contributions, Ingot, Legion parameters^ffffff\rApart from the attributes listed above, all other attributes transfer from the seller character to the buyer's overwritten character.\r\r^ff6fb33. Processing After a Character Transaction^ffffff\rAfter a character transaction succeeds, the seller character becomes a Level 15 low-level account, and the buyer character is overwritten with the character that was sold.\r\r^ff6fb34. Fee Calculation^ffffff\r^fffd44Handling fee = sale price × 10% + 50^ffffff\rExample: for a character priced at 100 yuan, handling fee = 100×10%+50 = 60\rNote: this 60 yuan handling fee is paid by the seller. The buyer pays only the 100 yuan character price; after the handling fee is deducted, the seller actually receives 40 yuan.\r\r^ff6fb35. Handling a Failed Purchase^ffffff\rIf the buyer's character does not meet the requirements, the purchase is considered failed, and you will be notified after payment. Please wait for the system to issue a refund; the transaction ends.",
	"^ff6fb3Seller (the party selling):^ffffff\rThe player who sells a character is in fact selling a designated character under that account.\r\r^ff6fb3Buyer (the party purchasing):^ffffff\rThe player who purchases a character must designate a low-level character for the transaction, that is, the “character to be overwritten”.\r\r^ff6fb3Character Sale Registration:^ffffff\rThe act of submitting a “character sale registration” at the game's functional NPC.\r\r^ff6fb3Registration Period:^ffffff\rA period allowing the seller to change their mind and providing protection against account theft. During this period the player has not actually begun selling the character; the player can log in and play normally. After logging in, the system will notify the player of the countdown to the end of the registration period. The registration period is at least 7 days and at most 10 days (including the buffer period). From the 7th day after registering, the player can perform “Character Sale” to sell the character. If the character still has not been sold by the 10th day after registration, its registration status is cancelled automatically.\r\r^ff6fb3Character Sale:^ffffff\rThe act of submitting a “Character Sale” at the game's functional NPC. When a player sells a character, a legality check is performed. If the check fails, the sale is not allowed and the character returns to the unregistered state. If the check passes, the character enters the “Display Period”.\r\r^ff6fb3Freeze Period:^ffffff\rThe time during which the character being sold is in the Display Period and the Sale Period. During this period the character cannot log in to the game.\r\r^ff6fb3Display Period:^ffffff\rThe character's information is shown on the website for the public, for other players to browse and report. The character is still on display and has not yet gone up for sale.\r\r^ff6fb3Sale Period:^ffffff\rThe character is formally on sale, available to be purchased at any time, and actual cash trading can take place.\r\r^ff6fb3Selling a Character:^ffffff\rMoving the character from inside the game to the trading center, after which the seller can perform specific operations on the website.\r\r^ff6fb3Listing:^ffffff\rThe process of setting a price for the character and putting it up for sale.\r\r^ff6fb3Delisting:^ffffff\rCancelling the character's listed status and stopping the sale, while the character is still held at the trading center.\r\r^ff6fb3Cancelling Consignment:^ffffff\rThe operation of retrieving an unlisted character stored at the trading center back into the game.\r\r^ff6fb3Successful Character Sale:^ffffff\rWhen a character sale succeeds, data transfer is performed."
}


