--Ways to Obtain Card-Flip Uses
CardInfo = 
"^ea8015Card-Flip Uses:\r^ffffffAfter reaching ^fffd44Hero 1^ffffff, completing certain daily quests and events grants card-flip uses. ^fffd44Some quests do not grant use rewards when completed via quick finish^ffffff.\r^ea8015Obtaining Rewards:\r^ffffffAfter flipping two cards, if the patterns match, the pair is successful. If the patterns do not match, the match fails and the cards are taken back.\r^ea8015Refresh:\r^ffffffThe cards reset daily at 00:00. After the reset all cards are taken back, but your card-flip uses remain unchanged. You can also use the item ^fffd44Card Collection Treasure^ffffff to refresh the cards.\r^ea8015Pair Matching Points:\r^ffffffEach successful pair awards Pair Matching points. The more pairs you match, the more points you earn. Pair Matching points can be used at #95704# to purchase various card collection gift packs.\r^ea8015Other:\rIf your quest list is already full, you may be unable to receive points. Please clear some quests from your quest list before playing Pair Matching."